update hadith set translation_ur = 'ابن مسعود رضی اللہ عنہ نے فرمایا: جو شخص محمد ﷺ کی وہ وصیت دیکھنا چاہے جس پر آپ کی مہر لگی ہو، وہ اللہ تعالیٰ کا یہ فرمان پڑھ لے: ﴿قُلْ تَعَالَوْا أَتْلُ مَا حَرَّمَ رَبُّكُمْ عَلَيْكُمْ أَلَّا تُشْرِكُوا بِهِ شَيْئًا﴾ (کہہ دیجیے: آؤ میں تمہیں پڑھ کر سناؤں جو تمہارے رب نے تم پر حرام کیا ہے، یہ کہ اس کے ساتھ کسی چیز کو شریک نہ ٹھہراؤ) سے لے کر ﴿وَأَنَّ هَذَا صِرَاطِي مُسْتَقِيمًا﴾ (اور یہ کہ یہی میرا سیدھا راستہ ہے) تک۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 60106;
update hadith set translation_ur = 'اور بخاری و مسلم میں عتبان رضی اللہ عنہ کی حدیث میں ہے: ”بے شک اللہ نے اس شخص پر جہنم کی آگ حرام کر دی ہے جس نے اللہ کی رضا چاہتے ہوئے لا الہ الا اللہ کہا۔“', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 60203;
update hadith set translation_ur = 'ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا: ”موسیٰ علیہ السلام نے عرض کیا: اے میرے رب! مجھے کوئی ایسی چیز سکھا جس کے ذریعے میں تیرا ذکر کروں اور تجھ سے دعا کروں۔ اللہ نے فرمایا: اے موسیٰ! لا الہ الا اللہ کہو۔ انہوں نے عرض کیا: اے میرے رب! یہ تو تیرے سب بندے کہتے ہیں۔ فرمایا: اے موسیٰ! اگر ساتوں آسمان اور میرے سوا ان کے سب رہنے والے اور ساتوں زمینیں ایک پلڑے میں ہوں اور لا الہ الا اللہ دوسرے پلڑے میں، تو لا الہ الا اللہ والا پلڑا ان سب پر بھاری ہو جائے۔“ اسے ابن حبان اور حاکم نے روایت کیا ہے اور حاکم نے اسے صحیح کہا ہے۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 60204;
update hadith set translation_ur = 'حصین بن عبد الرحمٰن کہتے ہیں: میں سعید بن جبیر کے پاس تھا تو انہوں نے پوچھا: تم میں سے کس نے وہ ستارہ دیکھا جو کل رات ٹوٹا تھا؟ میں نے کہا: میں نے۔ پھر میں نے کہا: سنیے، میں نماز میں نہیں تھا بلکہ مجھے (بچھو نے) ڈس لیا تھا۔ انہوں نے پوچھا: پھر تم نے کیا کیا؟ میں نے کہا: میں نے دم کروایا۔ انہوں نے پوچھا: تمہیں اس پر کس چیز نے آمادہ کیا؟ میں نے کہا: ایک حدیث نے جو شعبی نے ہمیں سنائی۔ انہوں نے پوچھا: انہوں نے تمہیں کیا سنایا؟ میں نے کہا: انہوں نے بریدہ بن حصیب رضی اللہ عنہ سے روایت کی کہ: ”دم صرف نظرِ بد یا زہریلے ڈنک کے لیے ہے۔“', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 60303;
update hadith set translation_ur = 'اور انہی (امام احمد) کی روایت میں عقبہ بن عامر رضی اللہ عنہ سے مرفوعاً ہے: ”جس نے تعویذ لٹکایا اللہ اس کا کام پورا نہ کرے، اور جس نے کوڑی (ودعہ) لٹکائی اللہ اسے سکون نہ دے۔“', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 60703;
update hadith set translation_ur = 'اور ابن ابی حاتم نے حذیفہ رضی اللہ عنہ سے روایت کیا کہ انہوں نے ایک آدمی کے ہاتھ میں بخار سے بچاؤ کا دھاگا دیکھا تو اسے کاٹ دیا اور یہ آیت پڑھی: ﴿وَمَا يُؤْمِنُ أَكْثَرُهُم بِاللَّهِ إِلَّا وَهُم مُّشْرِكُونَ﴾ (ان میں سے اکثر اللہ پر ایمان رکھنے کے باوجود مشرک ہی رہتے ہیں)۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 60705;
update hadith set translation_ur = 'سعید بن جبیر رحمہ اللہ نے فرمایا: جس نے کسی انسان سے تعویذ کاٹ دیا اسے ایک غلام آزاد کرنے کے برابر ثواب ملے گا۔ اسے وکیع نے روایت کیا ہے۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 60805;
update hadith set translation_ur = 'اور انہی (وکیع) کی روایت میں ابراہیم نخعی رحمہ اللہ سے ہے کہ انہوں نے کہا: (سلف) ہر قسم کے تعویذ ناپسند کرتے تھے، چاہے قرآن سے ہوں یا غیر قرآن سے۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 60806;
update hadith set translation_ur = 'علی رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے مجھے چار باتیں بتائیں: ”اللہ اس پر لعنت کرے جو غیر اللہ کے لیے ذبح کرے، اللہ اس پر لعنت کرے جو اپنے والدین پر لعنت کرے، اللہ اس پر لعنت کرے جو کسی بدعتی یا مجرم کو پناہ دے، اور اللہ اس پر لعنت کرے جو زمین کی حد بندی کے نشان بدل دے۔“ اسے مسلم نے روایت کیا ہے۔', explanation_ur = 'علی رضی اللہ عنہ سے پوچھا گیا: کیا رسول اللہ ﷺ نے آپ اہلِ بیت کو عام لوگوں کے سوا کوئی خاص چیز دی تھی؟ کیونکہ کچھ لوگوں کا گمان تھا کہ نبی ﷺ نے اپنے اہلِ بیت کو کوئی خاص علم، وصیت یا آئندہ کی خبر دی ہے جو دوسروں کو نہیں دی۔ علی رضی اللہ عنہ نے اس کی نفی کی اور فرمایا: آپ نے ہمیں کوئی ایسی چیز خاص نہیں دی جو سب لوگوں کو عام نہ ہو، سوائے اس کے جو میری تلوار کے غلاف میں ہے؛ یعنی ایک صحیفہ جو وہ تلوار کے تھیلے میں رکھتے تھے۔ پھر انہوں نے وہ صحیفہ نکالا جس میں لکھا تھا: اللہ اس پر لعنت کرے جو غیر اللہ کے لیے ذبح کرے — جیسے ذبیحہ پر اللہ کا نام نہ لینا، یا اولیاء اور قبروں کے لیے قربانیاں پیش کرنا وغیرہ؛ اللہ اس پر لعنت کرے جو زمین کی نشانیاں چرائے — یعنی پڑوسیوں کی زمینوں کے درمیان حد بندی کے نشان، اور ان کی چوری یہ ہے کہ دوسرے کی زمین کا کچھ حصہ ہتھیا لے؛ اللہ اس پر لعنت کرے جو اپنے والد پر لعنت کرے — خواہ براہِ راست یا سبب بن کر، مثلاً کسی کے باپ کو برا کہے تو وہ اس کے باپ کو برا کہے، اللہ تعالیٰ فرماتا ہے: ﴿فَلَا تَقُل لَّهُمَا أُفٍّ وَلَا تَنْهَرْهُمَا﴾ (انہیں اُف تک نہ کہو اور نہ جھڑکو)؛ اور اللہ اس پر لعنت کرے جو کسی مجرم کو پناہ دے — یعنی کسی جرم کرنے والے کو اپنے پاس ٹھہرائے، اسے قصاص سے بچائے اور اس سے اس کے جرم کی سزا دور کرے۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 61003;
update hadith set translation_ur = 'طارق بن شہاب رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا: ”ایک آدمی ایک مکھی کی وجہ سے جنت میں گیا اور ایک آدمی ایک مکھی کی وجہ سے جہنم میں گیا۔“ صحابہ نے عرض کیا: اے اللہ کے رسول! یہ کیسے؟ فرمایا: ”دو آدمی ایک قوم کے پاس سے گزرے جن کا ایک بت تھا، کوئی اس کے پاس سے اس وقت تک نہیں گزر سکتا تھا جب تک اس پر کچھ چڑھاوا نہ چڑھائے۔ انہوں نے ان میں سے ایک سے کہا: کچھ چڑھاوا چڑھاؤ۔ اس نے کہا: میرے پاس چڑھانے کو کچھ نہیں۔ انہوں نے کہا: چڑھاؤ، چاہے ایک مکھی ہی سہی۔ اس نے ایک مکھی چڑھا دی تو انہوں نے اس کا راستہ چھوڑ دیا، چنانچہ وہ جہنم میں گیا۔ اور انہوں نے دوسرے سے کہا: چڑھاوا چڑھاؤ۔ اس نے کہا: میں اللہ عزوجل کے سوا کسی کے لیے کچھ چڑھانے والا نہیں۔ تو انہوں نے اس کی گردن مار دی اور وہ جنت میں گیا۔“ اسے امام احمد نے روایت کیا ہے۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 61004;
update hadith set translation_ur = 'ثابت بن ضحاک رضی اللہ عنہ سے روایت ہے کہ ایک آدمی نے نذر مانی کہ وہ بُوانہ کے مقام پر اونٹ ذبح کرے گا۔ اس نے نبی ﷺ سے پوچھا تو آپ نے فرمایا: ”کیا وہاں جاہلیت کے بتوں میں سے کوئی بت تھا جس کی پوجا کی جاتی تھی؟“ لوگوں نے کہا: نہیں۔ فرمایا: ”کیا وہاں ان کا کوئی میلا (عید) لگتا تھا؟“ انہوں نے کہا: نہیں۔ تو رسول اللہ ﷺ نے فرمایا: ”اپنی نذر پوری کرو، کیونکہ اللہ کی نافرمانی میں نذر پوری نہیں کی جاتی اور نہ اس چیز میں جس کا ابن آدم مالک نہ ہو۔“ اسے ابو داود نے روایت کیا ہے اور اس کی سند بخاری و مسلم کی شرط پر ہے۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 61102;
update hadith set translation_ur = 'اور صحیح بخاری میں عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا: ”جس نے اللہ کی اطاعت کی نذر مانی وہ اس کی اطاعت کرے، اور جس نے اللہ کی نافرمانی کی نذر مانی وہ اس کی نافرمانی نہ کرے۔“', explanation_ur = 'نبی ﷺ نے فرمایا: جو شخص بدنی یا مالی مستحب عبادات کے ذریعے اللہ کی اطاعت کی نذر مانے، اس پر لازم ہے کہ اپنی نذر پوری کرے؛ جیسے کوئی ایک دن روزہ رکھنے یا کچھ صدقہ کرنے کی نذر مانے۔ اسی طرح اگر نذر کسی شرط سے مشروط ہو، جیسے غائب کی واپسی، مریض کی شفا یا کسی سودے کا مکمل ہونا، تو شرط پوری ہونے پر نذر پوری کرنا لازم ہے۔ اور جو اللہ کی نافرمانی کی نذر مانے، اس کے لیے وہ گناہ کا کام پورا کرنا جائز نہیں، جیسے چوری، گالی گلوچ یا کسی دوسرے کا مال صدقہ کرنا۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 61203;
update hadith set translation_ur = 'اور طبرانی نے اپنی سند سے روایت کیا کہ نبی ﷺ کے زمانے میں ایک منافق تھا جو مومنوں کو تکلیف دیتا تھا۔ تو ان میں سے بعض نے کہا: چلو ہم اس منافق کے خلاف رسول اللہ ﷺ سے فریاد کریں۔ تو نبی ﷺ نے فرمایا: ”مجھ سے فریاد نہیں کی جاتی، فریاد تو صرف اللہ عزوجل سے کی جاتی ہے۔“', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 61405;
update hadith set translation_ur = 'صحیح (بخاری) میں انس بن مالک رضی اللہ عنہ سے روایت ہے کہ احد کے دن نبی ﷺ زخمی ہوئے اور آپ کے سامنے کے دانت ٹوٹ گئے تو آپ نے فرمایا: ”وہ قوم کیسے کامیاب ہوگی جس نے اپنے نبی کو زخمی کر دیا؟!“ تو یہ آیت نازل ہوئی: ﴿لَيْسَ لَكَ مِنَ الْأَمْرِ شَيْءٌ﴾ (اس معاملے میں آپ کا کوئی اختیار نہیں)۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 61503;
update hadith set translation_ur = 'اور ایک روایت میں ہے کہ آپ ﷺ صفوان بن امیہ، سہیل بن عمرو اور حارث بن ہشام کے خلاف بددعا کرتے تھے، تو یہ آیت نازل ہوئی: ﴿لَيْسَ لَكَ مِنَ الْأَمْرِ شَيْءٌ﴾ (اس معاملے میں آپ کا کوئی اختیار نہیں)۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 61505;
update hadith set translation_ur = 'اور اسی میں ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ جب اللہ تعالیٰ نے آپ ﷺ پر یہ آیت نازل فرمائی: ﴿وَأَنذِرْ عَشِيرَتَكَ الْأَقْرَبِينَ﴾ (اور اپنے قریبی رشتہ داروں کو ڈرائیے) تو رسول اللہ ﷺ کھڑے ہوئے، صفا پہاڑی پر چڑھے اور فرمایا: ”اے قریش کی جماعت!“ — یا اسی طرح کا کوئی کلمہ — ”اپنی جانوں کو (عذاب سے) خرید لو، میں اللہ کے مقابلے میں تمہارے کچھ کام نہیں آ سکتا۔ اے عباس بن عبد المطلب! میں اللہ کے مقابلے میں تمہارے کچھ کام نہیں آ سکتا۔ اے صفیہ، رسول اللہ کی پھوپھی! میں اللہ کے مقابلے میں آپ کے کچھ کام نہیں آ سکتا۔ اے فاطمہ بنت محمد! میرے مال میں سے جو چاہو مانگ لو، (لیکن) میں اللہ کے مقابلے میں تمہارے کچھ کام نہیں آ سکتا۔“', explanation_ur = 'جب اللہ عزوجل نے یہ آیت نازل فرمائی: ﴿وَأَنذِرْ عَشِيرَتَكَ الْأَقْرَبِينَ﴾ (اور اپنے قریبی رشتہ داروں کو ڈرائیے)، تو نبی ﷺ نے اللہ کے حکم کی تعمیل میں فرمایا: اے قریش کے لوگو! اپنے آپ کو اللہ کے عذاب سے بچاؤ، میں اللہ کے مقابلے میں تمہارے کچھ کام نہیں آ سکتا؛ انسان کو اس کا ایمان ہی نجات دیتا ہے۔ اے بنی عبد المطلب! میں اللہ کے مقابلے میں تمہارے کچھ کام نہیں آ سکتا۔ اے عباس بن عبد المطلب! میں اللہ کے مقابلے میں تمہارے کچھ کام نہیں آ سکتا۔ اے صفیہ، رسول اللہ کی پھوپھی! میں اللہ کے مقابلے میں آپ کے کچھ کام نہیں آ سکتا۔ اے فاطمہ بنت رسول اللہ! دنیا کی جو چیز میرے بس میں ہو مجھ سے مانگ لو، میں تمہیں دے دوں گا، لیکن اللہ کے مقابلے میں تمہارے کچھ کام نہیں آ سکتا۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 61506;
update hadith set translation_ur = 'صحیح بخاری میں ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی ﷺ نے فرمایا: ”جب اللہ آسمان میں کسی بات کا فیصلہ فرماتا ہے تو فرشتے اس کے فرمان کے آگے عاجزی سے اپنے پر مارنے لگتے ہیں، گویا وہ (آواز) چکنے پتھر پر زنجیر (کی آواز) ہو، جو ان پر چھا جاتی ہے۔ ﴿حَتَّىٰ إِذَا فُزِّعَ عَن قُلُوبِهِمْ قَالُوا مَاذَا قَالَ رَبُّكُمْ ۖ قَالُوا الْحَقَّ ۖ وَهُوَ الْعَلِيُّ الْكَبِيرُ﴾ (یہاں تک کہ جب ان کے دلوں سے گھبراہٹ دور ہو جاتی ہے تو پوچھتے ہیں: تمہارے رب نے کیا فرمایا؟ وہ کہتے ہیں: حق فرمایا، اور وہی بلند و بالا اور بڑا ہے)۔ پھر اسے چوری چھپے سننے والے (شیاطین) سن لیتے ہیں“ — اور یہ چوری سے سننے والے ایک دوسرے کے اوپر اس طرح ہوتے ہیں؛ سفیان نے اپنی ہتھیلی سے اس کی کیفیت بتائی، اسے ترچھا کیا اور انگلیوں کے درمیان فاصلہ کیا — ”وہ ایک بات سن کر اپنے نیچے والے کو پہنچاتا ہے، پھر وہ اپنے نیچے والے کو، یہاں تک کہ وہ اسے جادوگر یا کاہن کی زبان پر ڈال دیتا ہے۔ کبھی شعلہ اسے بات پہنچانے سے پہلے ہی آ پکڑتا ہے اور کبھی وہ شعلہ پہنچنے سے پہلے بات ڈال دیتا ہے، پھر وہ (کاہن) اس کے ساتھ سو جھوٹ ملا دیتا ہے۔ تو کہا جاتا ہے: کیا اس نے ہمیں فلاں فلاں دن ایسا ایسا نہیں کہا تھا؟ چنانچہ اسی ایک بات کی وجہ سے اسے سچا مان لیا جاتا ہے جو آسمان سے سنی گئی تھی۔“', explanation_ur = 'ابو ہریرہ رضی اللہ عنہ نبی ﷺ سے روایت کرتے ہیں کہ جب اللہ عزوجل آسمان میں کسی معاملے کا فیصلہ فرماتا ہے تو فرشتے اللہ کے فرمان کے آگے عاجزی اور فرمانبرداری سے اپنے پر مارتے ہیں۔ آپ ﷺ نے اس سنی جانے والی آواز کو چکنے پتھر پر زنجیر کے گرنے کی آواز سے تشبیہ دی۔ جب ان کے دلوں سے گھبراہٹ دور ہوتی ہے تو فرشتے پوچھتے ہیں: تمہارے رب نے کیا فرمایا؟ تو مقرب فرشتے جیسے جبریل اور میکائیل جواب دیتے ہیں: اللہ نے حق فرمایا، اور وہ بلند و بالا اور بڑا ہے۔ پھر اس بات کو چوری چھپے سننے والے (جن) سن لیتے ہیں، جو ایک دوسرے کے اوپر اس طرح ہوتے ہیں — سفیان بن عیینہ نے اپنے دائیں ہاتھ کی انگلیاں کھول کر ایک کے اوپر ایک کھڑی کر کے اس کی کیفیت بتائی۔ کبھی شہاب (آگ کا شعلہ) سننے والے کو اس سے پہلے جا لیتا ہے کہ وہ بات اپنے ساتھی تک پہنچائے اور اسے جلا دیتا ہے، اور کبھی شہاب اسے نہیں پکڑ پاتا یہاں تک کہ وہ بات اپنے نیچے والے تک پہنچا دیتا ہے، یہاں تک کہ وہ اسے زمین تک پہنچا دیتے ہیں اور وہ بات جادوگر یعنی نجومی کے منہ پر ڈالی جاتی ہے۔ وہ اس ایک بات کے ساتھ سو جھوٹ ملا دیتا ہے، پھر اس کے جھوٹوں میں بھی اسے سچا مانا جاتا ہے اور سننے والے کہتے ہیں: کیا اس نے ہمیں فلاں دن یہ خبر نہیں دی تھی کہ ایسا ایسا ہوگا، اور ہم نے اسے سچ پایا؟ یہ سب اس ایک بات کی وجہ سے ہوتا ہے جو آسمان سے سنی گئی تھی۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 61602;
update hadith set translation_ur = 'نواس بن سمعان رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا: ”جب اللہ تعالیٰ کسی حکم کی وحی کرنا چاہتا ہے تو وحی کے ساتھ کلام فرماتا ہے، تو آسمانوں پر اللہ عزوجل کے خوف سے کپکپی“ — یا فرمایا: ”شدید لرزہ طاری ہو جاتا ہے۔ جب آسمان والے یہ سنتے ہیں تو بے ہوش ہو جاتے ہیں“ — یا فرمایا: ”اللہ کے لیے سجدے میں گر پڑتے ہیں۔ تو سب سے پہلے جبریل سر اٹھاتے ہیں، اللہ ان سے اپنی وحی میں سے جو چاہتا ہے کلام فرماتا ہے۔ پھر جبریل فرشتوں کے پاس سے گزرتے ہیں؛ جس آسمان سے بھی گزرتے ہیں اس کے فرشتے پوچھتے ہیں: اے جبریل! ہمارے رب نے کیا فرمایا؟ وہ کہتے ہیں: حق فرمایا، اور وہی بلند و بالا اور بڑا ہے۔ تو وہ سب بھی وہی کہتے ہیں جو جبریل نے کہا۔ پھر جبریل وحی کو وہاں تک پہنچا دیتے ہیں جہاں اللہ عزوجل نے انہیں حکم دیا ہو۔“', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 61603;
update hadith set translation_ur = 'ابو العباس (ابن تیمیہ رحمہ اللہ) نے فرمایا: اللہ تعالیٰ نے اپنے سوا ہر اس چیز کی نفی کر دی جس سے مشرکین وابستہ ہوتے ہیں؛ اس نے نفی کی کہ اس کے سوا کسی کی بادشاہی ہو، یا اس میں کسی کا حصہ ہو، یا کوئی اللہ کا مددگار ہو۔ اب صرف شفاعت باقی رہ گئی تو اس نے واضح کر دیا کہ وہ صرف اسی کے لیے فائدہ دے گی جس کے لیے رب اجازت دے، جیسا کہ فرمایا: ﴿وَلَا يَشْفَعُونَ إِلَّا لِمَنِ ارْتَضَىٰ﴾ (اور وہ صرف اسی کی سفارش کریں گے جس سے وہ راضی ہو)۔ لہٰذا وہ شفاعت جس کا مشرکین گمان رکھتے ہیں، وہ معدوم ہے جیسا کہ قرآن نے اس کی نفی کی۔ اور نبی ﷺ نے خبر دی کہ آپ (قیامت کے دن) آئیں گے، اپنے رب کو سجدہ کریں گے اور اس کی حمد کریں گے، پہلے شفاعت سے ابتدا نہیں کریں گے، پھر آپ سے کہا جائے گا: ”اپنا سر اٹھائیے، کہیے آپ کی بات سنی جائے گی، مانگیے آپ کو دیا جائے گا، اور شفاعت کیجیے آپ کی شفاعت قبول کی جائے گی۔“ اور ابو ہریرہ رضی اللہ عنہ نے پوچھا: اے اللہ کے رسول! آپ کی شفاعت کا سب سے زیادہ حق دار کون ہوگا؟ فرمایا: ”جس نے اپنے دل کے اخلاص سے لا الہ الا اللہ کہا۔“ تو یہ شفاعت اخلاص والوں کے لیے ہے، اللہ کے ساتھ شرک کرنے والے کے لیے نہیں ہوگی۔ اور اس کی حقیقت یہ ہے کہ اللہ سبحانہ و تعالیٰ ہی اخلاص والوں پر فضل فرماتا ہے اور اس شخص کی دعا کے ذریعے انہیں بخش دیتا ہے جسے اس نے شفاعت کی اجازت دی تاکہ اس کا اکرام کرے اور وہ مقامِ محمود پائے۔ پس وہ شفاعت جس کی قرآن نے نفی کی ہے وہ ہے جس میں شرک ہو، اسی لیے اس نے کئی مقامات پر اپنی اجازت سے شفاعت ثابت کی ہے، اور نبی ﷺ نے واضح فرما دیا کہ وہ صرف توحید اور اخلاص والوں کے لیے ہوگی۔ ان کا کلام ختم ہوا۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 61707;
update hadith set translation_ur = 'اور ابن القیم رحمہ اللہ نے فرمایا: سلف میں سے کئی لوگوں نے کہا ہے: جب وہ (قومِ نوح کے نیک لوگ) فوت ہو گئے تو لوگ ان کی قبروں پر جم کر بیٹھنے لگے، پھر ان کی تصویریں (مجسمے) بنائے، پھر جب لمبا زمانہ گزر گیا تو ان کی عبادت کرنے لگے۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 61903;
update hadith set translation_ur = 'صحیح (بخاری) میں عائشہ رضی اللہ عنہا سے روایت ہے کہ ام سلمہ رضی اللہ عنہا نے رسول اللہ ﷺ سے ایک گرجا کا ذکر کیا جو انہوں نے حبشہ کی سرزمین میں دیکھا تھا اور اس میں موجود تصویروں کا۔ تو آپ ﷺ نے فرمایا: ”یہ وہ لوگ ہیں کہ جب ان میں کوئی نیک آدمی یا نیک بندہ فوت ہو جاتا تو اس کی قبر پر مسجد بنا لیتے اور اس میں یہ تصویریں بنا دیتے۔ یہ لوگ اللہ کے نزدیک بدترین مخلوق ہیں۔“ پس انہوں نے دو فتنے جمع کر دیے: قبروں کا فتنہ اور مجسموں کا فتنہ۔', explanation_ur = 'ام سلمہ رضی اللہ عنہا نے نبی ﷺ کے مرضِ وفات میں آپ کے سامنے عیسائیوں کے گرجا میں دیکھی ہوئی انسانوں کی تصویروں کا ذکر کیا، تو آپ ﷺ نے وہ سبب بیان فرمایا جس کی وجہ سے انہوں نے یہ تصویریں بنائیں؛ اور وہ ہے نیک لوگوں کی تعظیم میں غلو، جس نے انہیں ان کی قبروں پر مسجدیں بنانے اور ان میں ان کی تصویریں لگانے تک پہنچا دیا۔ پھر آپ نے ایسا کرنے والوں کا حکم بیان فرمایا کہ وہ بدترین لوگ ہیں؛ کیونکہ انہوں نے اس کام میں دو ممنوع چیزیں جمع کر دیں: قبروں کو مسجدیں بنانے کا فتنہ، اور مجسموں کی تعظیم کا فتنہ جو شرک تک لے جاتا ہے۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 62001;
update hadith set translation_ur = 'اور ابن جریر نے اپنی سند سے سفیان، منصور اور مجاہد سے اللہ تعالیٰ کے فرمان ﴿أَفَرَأَيْتُمُ اللَّاتَ وَالْعُزَّىٰ﴾ (بھلا تم نے لات اور عزیٰ کو دیکھا؟) کے بارے میں روایت کیا کہ انہوں نے کہا: وہ (لات) حاجیوں کے لیے ستو گھولا کرتا تھا، جب وہ مر گیا تو لوگ اس کی قبر پر جم کر بیٹھنے لگے۔ اور ابو الجوزاء نے ابن عباس رضی اللہ عنہما سے بھی یہی روایت کیا کہ وہ حاجیوں کے لیے ستو گھولا کرتا تھا۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 62102;
update hadith set translation_ur = 'ابن عباس رضی اللہ عنہما سے روایت ہے کہ رسول اللہ ﷺ نے قبروں کی زیارت کرنے والی عورتوں پر، اور قبروں پر مسجدیں بنانے اور چراغ جلانے والوں پر لعنت فرمائی۔ اسے اصحابِ سنن نے روایت کیا ہے۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 62103;
update hadith set translation_ur = 'عمر رضی اللہ عنہ نے فرمایا: ”الجبت“ جادو ہے اور ”الطاغوت“ شیطان ہے۔ اور جابر رضی اللہ عنہ نے فرمایا: ”طواغیت“ وہ کاہن ہیں جن پر شیاطین اترتے تھے، ہر قبیلے میں ایک ہوتا تھا۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 62403;
update hadith set translation_ur = 'جندب رضی اللہ عنہ سے مرفوعاً روایت ہے: ”جادوگر کی سزا تلوار سے گردن مارنا ہے۔“ اسے ترمذی نے روایت کیا اور کہا: صحیح یہ ہے کہ یہ موقوف (صحابی کا قول) ہے۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 62405;
update hadith set translation_ur = 'اور حفصہ رضی اللہ عنہا سے صحیح طور پر ثابت ہے کہ انہوں نے اپنی ایک لونڈی کو قتل کرنے کا حکم دیا جس نے ان پر جادو کیا تھا، چنانچہ اسے قتل کر دیا گیا۔ اسی طرح جندب رضی اللہ عنہ سے بھی صحیح ثابت ہے۔ امام احمد نے فرمایا: (جادوگر کا قتل) رسول اللہ ﷺ کے تین صحابہ سے ثابت ہے۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 62407;
update hadith set translation_ur = 'امام احمد نے فرمایا: ہم سے محمد بن جعفر نے بیان کیا، ان سے عوف نے حیان بن العلاء سے، ان سے قطن بن قبیصہ نے اپنے والد سے روایت کی کہ انہوں نے نبی ﷺ کو فرماتے سنا: ”پرندے اڑا کر فال لینا، زمین پر لکیریں کھینچنا اور بدشگونی لینا جبت (شیطانی کام) میں سے ہیں۔“ عوف نے کہا: ”العیافہ“ پرندوں کو اڑانا ہے، اور ”الطرق“ زمین پر کھینچی جانے والی لکیر ہے۔ اور ”الجبت“ کے بارے میں حسن نے کہا: شیطان کی آواز ہے۔ اس کی سند جید ہے۔ اور ابو داود، نسائی اور ابن حبان نے اپنی صحیح میں اس کا مرفوع حصہ روایت کیا ہے۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 62501;
update hadith set translation_ur = 'اور نسائی میں ابو ہریرہ رضی اللہ عنہ کی حدیث ہے: ”جس نے گرہ لگائی پھر اس میں پھونکا اس نے جادو کیا، اور جس نے جادو کیا اس نے شرک کیا، اور جس نے کوئی چیز لٹکائی وہ اسی کے سپرد کر دیا گیا۔“', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 62503;
update hadith set translation_ur = 'اور بخاری و مسلم میں ابن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا: ”بے شک بعض بیان (فصاحت) جادو ہوتا ہے۔“', explanation_ur = 'مشرق کی جانب سے، یعنی عراق سے — جو مدینہ کے مشرق میں ہے — دو آدمی آئے اور انہوں نے لوگوں سے خطاب کیا تو لوگ ان کے حسنِ بیان پر حیران رہ گئے۔ تو نبی ﷺ نے فرمایا: بے شک کچھ بیان — یعنی مقصد کو بلیغ ترین الفاظ میں ظاہر کرنا — جادو ہوتا ہے؛ یا فرمایا: بعض بیان جادو ہوتا ہے (راوی کو شک ہے)۔ کیونکہ کچھ بیان سننے والوں کے دلوں کو بولنے والے کے مقصد کی طرف پھیر دیتا ہے، چاہے وہ حق نہ ہو، جیسا کہ جادو کرتا ہے۔ اگر حدیث سے تعریف مراد ہو تو معنی یہ ہے کہ اس سے دل مائل کیے جاتے ہیں، ناراض کو راضی کیا جاتا ہے اور مشکل کو آسان بنایا جاتا ہے؛ اور اگر مذمت مراد ہو تو معنی یہ ہے کہ یہ حقائق کو الٹ دیتا ہے اور باطل کو جادو کی طرح خوشنما بنا دیتا ہے؛ اسی لیے فرمایا: ”بعض بیان“۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 62505;
update hadith set translation_ur = 'ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی ﷺ نے فرمایا: ”جو کسی کاہن کے پاس گیا اور اس کی بات کی تصدیق کی، اس نے اس چیز کا انکار کیا جو محمد ﷺ پر نازل کی گئی۔“ اسے ابو داود نے روایت کیا ہے۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 62602;
update hadith set translation_ur = 'اور سنن اربعہ اور حاکم میں — اور حاکم نے کہا: یہ بخاری و مسلم کی شرط پر صحیح ہے — روایت ہے: ”جو کسی عراف (غیب کی باتیں بتانے والے) یا کاہن کے پاس گیا اور اس کی بات کی تصدیق کی، اس نے اس چیز کا انکار کیا جو محمد ﷺ پر نازل کی گئی۔“', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 62603;
update hadith set translation_ur = 'اور ابو یعلیٰ نے جید سند کے ساتھ ابن مسعود رضی اللہ عنہ سے اسی کی مثل موقوفاً روایت کیا ہے۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 62604;
update hadith set translation_ur = 'اور طبرانی نے ”الاوسط“ میں حسن سند کے ساتھ ابن عباس رضی اللہ عنہما کی حدیث سے اسے روایت کیا ہے، مگر اس میں ”اور جو کسی کاہن کے پاس گیا…“ آخر تک کے الفاظ نہیں ہیں۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 62606;
update hadith set translation_ur = 'بغوی رحمہ اللہ نے فرمایا: عراف وہ ہے جو ایسے قرائن کے ذریعے معاملات جاننے کا دعویٰ کرے جن سے وہ چوری شدہ چیز اور گمشدہ چیز کی جگہ وغیرہ پر استدلال کرتا ہے۔ اور کہا گیا ہے کہ وہی کاہن ہے۔ اور کاہن وہ ہے جو غیب کی خبریں دے، اور کہا گیا ہے: جو دل کی باتیں بتائے۔ اور ابو العباس ابن تیمیہ رحمہ اللہ نے فرمایا: عراف کاہن، نجومی، رمّال اور ان جیسے ان سب لوگوں کا نام ہے جو ان طریقوں سے معاملات جاننے کی بات کرتے ہیں۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 62607;
update hadith set translation_ur = 'اور ابن عباس رضی اللہ عنہما نے ان لوگوں کے بارے میں جو ”ابجد“ (کے حروف) لکھتے اور ستاروں میں دیکھتے ہیں، فرمایا: میں نہیں سمجھتا کہ جو ایسا کرے اس کا اللہ کے ہاں کوئی حصہ ہو۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 62608;
update hadith set translation_ur = 'اور صحیح بخاری میں قتادہ سے روایت ہے کہ میں نے سعید بن مسیب سے کہا: ایک آدمی پر جادو ہے، یا اسے اس کی بیوی سے روک دیا گیا ہے، کیا اس کا جادو کھولا جائے یا اس کا توڑ (نشرہ) کیا جائے؟ انہوں نے کہا: اس میں کوئی حرج نہیں، وہ تو اس سے اصلاح ہی چاہتے ہیں، اور جو چیز فائدہ دے اس سے منع نہیں کیا گیا۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 62702;
update hadith set translation_ur = 'ابن القیم رحمہ اللہ نے فرمایا: نشرہ کا مطلب ہے جادو زدہ شخص سے جادو اتارنا، اور اس کی دو قسمیں ہیں: ایک یہ کہ اسی جیسے جادو سے اتارا جائے، یہ شیطان کا کام ہے اور حسن بصری کا قول اسی پر محمول ہے؛ اس میں جادو اتارنے والا اور اتروانے والا دونوں شیطان کا تقرب حاصل کرتے ہیں تو وہ جادو زدہ سے اپنا عمل ہٹا لیتا ہے۔ اور دوسری قسم: دم، پناہ کے کلمات، دعاؤں اور جائز دواؤں کے ذریعے جادو اتارنا، یہ جائز ہے۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 62704;
update hadith set translation_ur = 'اور ابو داود نے صحیح سند کے ساتھ عقبہ بن عامر رضی اللہ عنہ سے روایت کیا کہ رسول اللہ ﷺ کے پاس بدشگونی کا ذکر ہوا تو آپ نے فرمایا: ”اس میں سب سے اچھی چیز نیک فال ہے، اور یہ کسی مسلمان کو (اس کے کام سے) نہ روکے۔ جب تم میں سے کوئی ناپسندیدہ چیز دیکھے تو کہے: اے اللہ! بھلائیاں صرف تو ہی لاتا ہے اور برائیاں صرف تو ہی دور کرتا ہے، اور نیکی کرنے کی طاقت اور برائی سے بچنے کی قوت صرف تیری ہی توفیق سے ہے۔“', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 62805;
update hadith set translation_ur = 'اور انہی (امام احمد) کی روایت میں فضل بن عباس رضی اللہ عنہما کی حدیث ہے: ”بدشگونی وہ ہے جو تمہیں (کسی کام پر) آگے بڑھا دے یا (اس سے) روک دے۔“', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 62808;
update hadith set translation_ur = 'امام بخاری نے اپنی صحیح میں فرمایا: قتادہ نے کہا: اللہ نے یہ ستارے تین مقاصد کے لیے پیدا کیے: آسمان کی زینت، شیاطین کو مارنے کے لیے اور نشانیاں جن سے راستہ معلوم کیا جائے۔ جس نے ان میں اس کے علاوہ کوئی تاویل کی اس نے غلطی کی، اپنا حصہ ضائع کیا اور ایسی چیز کا تکلف کیا جس کا اسے علم نہیں۔ (قتادہ نے) چاند کی منزلیں سیکھنا ناپسند کیا اور ابن عیینہ نے بھی اس کی اجازت نہیں دی — یہ حرب نے ان دونوں سے نقل کیا ہے — جبکہ امام احمد اور اسحاق نے منزلیں سیکھنے کی اجازت دی۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 62901;
update hadith set translation_ur = 'ابو مالک اشعری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا: ”میری امت میں جاہلیت کے کاموں میں سے چار کام ایسے ہیں جنہیں وہ نہیں چھوڑیں گے: حسب پر فخر کرنا، نسب میں طعن کرنا، ستاروں سے بارش طلب کرنا، اور میت پر نوحہ کرنا۔“ اور فرمایا: ”نوحہ کرنے والی اگر اپنی موت سے پہلے توبہ نہ کرے تو قیامت کے دن اسے اس حال میں کھڑا کیا جائے گا کہ اس پر تارکول کا کرتا اور خارش کی قمیص ہوگی۔“ اسے مسلم نے روایت کیا ہے۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 63002;
update hadith set translation_ur = 'اور بخاری و مسلم میں ابن عباس رضی اللہ عنہما کی حدیث اسی معنی میں ہے، اور اس میں ہے: ”بعض نے کہا: فلاں فلاں ستارے نے سچ کر دکھایا۔“ تو اللہ نے یہ آیات نازل فرمائیں: ﴿فَلَا أُقْسِمُ بِمَوَاقِعِ النُّجُومِ﴾ (پس میں ستاروں کے گرنے کی جگہوں کی قسم کھاتا ہوں) سے ﴿وَتَجْعَلُونَ رِزْقَكُمْ أَنَّكُمْ تُكَذِّبُونَ﴾ (اور تم نے اپنا حصہ یہی بنا رکھا ہے کہ جھٹلاتے رہو) تک۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 63004;
update hadith set translation_ur = 'اور بخاری و مسلم میں انہی (انس رضی اللہ عنہ) سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا: ”تین باتیں جس میں ہوں وہ ان کے ذریعے ایمان کی مٹھاس پا لیتا ہے: یہ کہ اللہ اور اس کا رسول اسے باقی سب سے زیادہ محبوب ہوں، یہ کہ وہ کسی شخص سے صرف اللہ کے لیے محبت کرے، اور یہ کہ وہ کفر میں لوٹنے کو — جبکہ اللہ نے اسے اس سے بچا لیا — ایسے ہی ناپسند کرے جیسے آگ میں ڈالے جانے کو ناپسند کرتا ہے۔“', explanation_ur = 'نبی ﷺ نے تین خصلتوں کی خبر دی کہ جو انہیں اپنے اندر پائے اس نے ایمان کی مٹھاس پا لی۔ ایمان کی مٹھاس سے مراد ہے: نیکیوں میں لذت پانا، دین کی خاطر مشقتیں برداشت کرنا اور آخرت کی نہ ختم ہونے والی نعمتوں کی رغبت میں انہیں دنیا کے سامان پر ترجیح دینا؛ یہ ایسی چیز ہے جسے مومن اپنے دل میں اسی طرح محسوس کرتا ہے جیسے کھانے پینے کی مٹھاس محسوس کرتا ہے۔ پہلی: اللہ اور اس کا رسول بندے کو ہر چیز سے زیادہ محبوب ہوں، وہ ان کی محبت پر کسی چیز کی محبت کو مقدم نہ کرے، جیسا کہ اللہ تعالیٰ نے فرمایا: ﴿قُلْ إِن كُنتُمْ تُحِبُّونَ اللَّهَ فَاتَّبِعُونِي يُحْبِبْكُمُ اللَّهُ﴾ (کہہ دیجیے: اگر تم اللہ سے محبت رکھتے ہو تو میری پیروی کرو، اللہ تم سے محبت کرے گا) [آل عمران: 31]۔ دوسری: اپنے مومن بھائی سے صرف اللہ کی خاطر خالص محبت کرے، کہ یہ تعلق دنیاوی اغراض اور انسانی مفادات سے پاک ہو؛ کیونکہ جو کسی غرض کی خاطر محبت کرتا ہے، اس کی محبت غرض پوری ہونے یا اس سے مایوس ہونے پر ختم ہو جاتی ہے، جبکہ مومن کی محبت ہمیشہ کا فریضہ ہے، اغراض ہوں یا نہ ہوں؛ کیونکہ وہ اس سے اس کے ایمان کی وجہ سے محبت کرتا ہے، اور مومنوں سے محبت ان عبادات میں سے ہے جن میں نیت کا اخلاص ضروری ہے۔ تیسری: کفر کی طرف لوٹنے کو ایسا ہی ناپسند کرے جیسے آگ میں ڈالے جانے کو ناپسند کرتا ہے؛ اس ناپسندیدگی کا سبب یہ ہے کہ مومن پر اسلام کی خوبی اور جہالتوں کی خرابیاں اور کفر کی قباحت واضح ہو چکی ہے، اور اس کے دل میں ایمان کا نور داخل ہو چکا ہے۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 63104;
update hadith set translation_ur = 'اور ایک روایت میں ہے: ”کوئی بندہ ایمان کی مٹھاس نہیں پا سکتا جب تک کہ وہ اللہ کے لیے محبت نہ کرے اور اللہ کے لیے بغض نہ رکھے۔“', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 63105;
update hadith set translation_ur = 'ابن عباس رضی اللہ عنہما نے فرمایا: جو اللہ کے لیے محبت کرے، اللہ کے لیے بغض رکھے، اللہ کے لیے دوستی کرے اور اللہ کے لیے دشمنی کرے، تو اللہ کی ولایت (دوستی) اسی سے حاصل ہوتی ہے۔ اور کوئی بندہ ایمان کا ذائقہ نہیں پا سکتا — چاہے اس کی نمازیں اور روزے کتنے ہی زیادہ ہوں — جب تک وہ ایسا نہ ہو جائے۔ اور اب لوگوں کا عام بھائی چارہ دنیا کے معاملات پر ہو گیا ہے، اور یہ اپنے اہل کو کچھ فائدہ نہیں دے گا۔ اسے ابن جریر نے روایت کیا ہے۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 63106;
update hadith set translation_ur = 'اور ابن عباس رضی اللہ عنہما نے اللہ تعالیٰ کے فرمان ﴿وَتَقَطَّعَتْ بِهِمُ الْأَسْبَابُ﴾ (اور ان کے سارے تعلقات کٹ جائیں گے) کے بارے میں فرمایا: (اس سے مراد) دوستیاں ہیں۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 63107;
update hadith set translation_ur = 'ابو سعید رضی اللہ عنہ سے مرفوعاً روایت ہے: ”یقین کی کمزوری میں سے یہ ہے کہ تم اللہ کو ناراض کر کے لوگوں کو راضی کرو، اللہ کے دیے ہوئے رزق پر لوگوں کی تعریف کرو، اور جو اللہ نے تمہیں نہیں دیا اس پر لوگوں کی مذمت کرو۔ بے شک اللہ کا رزق نہ کسی لالچی کی لالچ کھینچ کر لاتی ہے اور نہ کسی ناپسند کرنے والے کی ناپسندیدگی اسے روک سکتی ہے۔“', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 63204;
update hadith set translation_ur = 'عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا: ”جس نے لوگوں کی ناراضی مول لے کر اللہ کی رضا چاہی، اللہ اس سے راضی ہو جاتا ہے اور لوگوں کو بھی اس سے راضی کر دیتا ہے۔ اور جس نے اللہ کو ناراض کر کے لوگوں کی رضا چاہی، اللہ اس سے ناراض ہو جاتا ہے اور لوگوں کو بھی اس سے ناراض کر دیتا ہے۔“ اسے ابن حبان نے اپنی صحیح میں روایت کیا ہے۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 63205;
update hadith set translation_ur = 'ابن عباس رضی اللہ عنہما نے فرمایا: ﴿حَسْبُنَا اللَّهُ وَنِعْمَ الْوَكِيلُ﴾ (ہمیں اللہ کافی ہے اور وہ بہترین کارساز ہے) — یہ کلمہ ابراہیم علیہ السلام نے اس وقت کہا جب انہیں آگ میں ڈالا گیا، اور محمد ﷺ نے اس وقت کہا جب لوگوں نے آپ سے کہا: ﴿إِنَّ النَّاسَ قَدْ جَمَعُوا لَكُمْ فَاخْشَوْهُمْ فَزَادَهُمْ إِيمَانًا وَقَالُوا حَسْبُنَا اللَّهُ وَنِعْمَ الْوَكِيلُ﴾ (لوگوں نے تمہارے خلاف بڑا لشکر جمع کر لیا ہے، ان سے ڈرو؛ تو اس بات نے ان کا ایمان اور بڑھا دیا اور انہوں نے کہا: ہمیں اللہ کافی ہے اور وہ بہترین کارساز ہے)۔ اسے بخاری اور نسائی نے روایت کیا ہے۔', explanation_ur = 'ابن عباس رضی اللہ عنہما بیان کرتے ہیں کہ اللہ تعالیٰ کا فرمان ﴿حَسْبُنَا اللَّهُ وَنِعْمَ الْوَكِيلُ﴾ (ہمیں اللہ کافی ہے اور وہ بہترین کارساز ہے) ابراہیم علیہ السلام نے اس وقت کہا جب انہیں آگ میں ڈالا گیا، اور محمد ﷺ نے اس وقت کہا جب لوگوں نے آپ سے کہا: ﴿إِنَّ النَّاسَ قَدْ جَمَعُوا لَكُمْ﴾ (لوگوں نے — یعنی ابو سفیان اور اس کے ساتھیوں نے — تمہارے خلاف لشکر جمع کر لیا ہے) تم پر حملے کے ارادے سے۔ ابو سفیان نے سن تین ہجری میں احد سے واپسی پر پکارا تھا: اے محمد! اگر چاہو تو اگلے سال بدر کے موسم میں ہمارا مقابلہ ہوگا۔ آپ ﷺ نے فرمایا: ان شاء اللہ۔ اگلے سال وہ اہلِ مکہ کو لے کر نکلا اور مرّ الظہران میں پڑاؤ کیا، تو اللہ نے اس کے دل میں رعب ڈال دیا اور اس نے واپسی کا ارادہ کیا۔ اس کے پاس سے عبد القیس کا ایک قافلہ گزرا جو غلہ لینے مدینہ جا رہا تھا، تو اس نے ان سے ایک اونٹ کشمش کے بدلے یہ شرط کی کہ وہ مسلمانوں کو (نکلنے سے) روکیں۔ اور کہا گیا ہے کہ وہ نعیم بن مسعود سے ملا جو عمرے کے لیے آیا تھا اور اس سے یہی کام کرنے کو کہا اور دس اونٹ دینے کا وعدہ کیا۔ نعیم نکلے تو مسلمانوں کو تیاری کرتے پایا اور ان سے کہا: اگر وہ تمہارے گھروں میں آ گئے تو تم میں سے کوئی نہیں بچے گا سوائے کسی بھاگنے والے کے، تو کیا تم نکلنا چاہتے ہو جبکہ انہوں نے تمہارے خلاف لشکر جمع کر لیا ہے؟ ﴿فَاخْشَوْهُمْ﴾ (ان سے ڈرو) اور ان کی طرف نہ نکلو۔ ﴿فَزَادَهُمْ إِيمَانًا﴾ (تو اس بات نے ان کا ایمان اور بڑھا دیا) — انہوں نے اس کی پروا نہ کی اور کمزور نہ پڑے، بلکہ اللہ پر ان کا یقین اور پختہ ہو گیا اور انہوں نے جہاد میں نیت خالص کر لی؛ اس میں دلیل ہے کہ ایمان بڑھتا اور گھٹتا ہے۔ ﴿وَقَالُوا حَسْبُنَا اللَّهُ﴾ یعنی ہمیں اللہ کافی ہے، ﴿وَنِعْمَ الْوَكِيلُ﴾ اور وہی بہترین سہارا ہے۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 63305;
update hadith set translation_ur = 'ابن عباس رضی اللہ عنہما سے روایت ہے کہ رسول اللہ ﷺ سے کبیرہ گناہوں کے بارے میں پوچھا گیا تو آپ نے فرمایا: ”اللہ کے ساتھ شرک کرنا، اللہ کی رحمت سے مایوس ہونا، اور اللہ کی (پوشیدہ) تدبیر سے بے خوف ہو جانا۔“', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 63403;
update hadith set translation_ur = 'علقمہ رحمہ اللہ نے (آیت ﴿وَمَن يُؤْمِن بِاللَّهِ يَهْدِ قَلْبَهُ﴾ کی تفسیر میں) فرمایا: یہ وہ آدمی ہے جسے کوئی مصیبت پہنچے تو وہ جان لے کہ یہ اللہ کی طرف سے ہے، چنانچہ وہ راضی رہے اور اسے تسلیم کر لے۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 63502;
update hadith set translation_ur = 'اور ابن عباس رضی اللہ عنہما نے فرمایا: قریب ہے کہ تم پر آسمان سے پتھر برسیں؛ میں کہتا ہوں: رسول اللہ ﷺ نے فرمایا، اور تم کہتے ہو: ابو بکر اور عمر نے کہا؟!', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 63801;
update hadith set translation_ur = 'اور امام احمد بن حنبل رحمہ اللہ نے فرمایا: مجھے ان لوگوں پر تعجب ہے جو (حدیث کی) سند اور اس کی صحت جان لیتے ہیں پھر بھی سفیان کی رائے کی طرف جاتے ہیں، حالانکہ اللہ تعالیٰ فرماتا ہے: ﴿فَلْيَحْذَرِ الَّذِينَ يُخَالِفُونَ عَنْ أَمْرِهِ أَن تُصِيبَهُمْ فِتْنَةٌ أَوْ يُصِيبَهُمْ عَذَابٌ أَلِيمٌ﴾ (جو لوگ رسول کے حکم کی مخالفت کرتے ہیں انہیں ڈرنا چاہیے کہ کہیں ان پر کوئی فتنہ نہ آ پڑے یا دردناک عذاب نہ آ پہنچے)۔ کیا تم جانتے ہو فتنہ کیا ہے؟ فتنہ شرک ہے؛ ہو سکتا ہے کہ جب وہ آپ ﷺ کی کوئی بات رد کرے تو اس کے دل میں کچھ کجی آ جائے اور وہ ہلاک ہو جائے۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 63802;
update hadith set translation_ur = 'اور شعبی رحمہ اللہ نے فرمایا: منافقوں میں سے ایک آدمی اور یہودیوں میں سے ایک آدمی کے درمیان جھگڑا تھا۔ یہودی نے کہا: ہم محمد (ﷺ) سے فیصلہ کرواتے ہیں — کیونکہ وہ جانتا تھا کہ آپ رشوت نہیں لیتے — اور منافق نے کہا: ہم یہودیوں سے فیصلہ کرواتے ہیں — کیونکہ وہ جانتا تھا کہ وہ رشوت لیتے ہیں۔ پھر دونوں اس بات پر متفق ہو گئے کہ جہینہ کے ایک کاہن کے پاس جا کر اس سے فیصلہ کروائیں، تو یہ آیت نازل ہوئی: ﴿أَلَمْ تَرَ إِلَى الَّذِينَ يَزْعُمُونَ أَنَّهُمْ آمَنُوا بِمَا أُنزِلَ إِلَيْكَ وَمَا أُنزِلَ مِن قَبْلِكَ﴾ (کیا آپ نے ان لوگوں کو نہیں دیکھا جو دعویٰ کرتے ہیں کہ وہ اس پر ایمان لائے جو آپ پر اور آپ سے پہلے نازل کیا گیا)۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 63906;
update hadith set translation_ur = 'اور کہا گیا ہے کہ یہ آیت دو آدمیوں کے بارے میں نازل ہوئی جو جھگڑ پڑے تھے؛ ان میں سے ایک نے کہا: ہم نبی ﷺ کے پاس مقدمہ لے چلتے ہیں، اور دوسرے نے کہا: کعب بن اشرف کے پاس۔ پھر وہ دونوں عمر بن خطاب رضی اللہ عنہ کے پاس گئے، ان میں سے ایک نے پورا قصہ سنایا تو عمر نے اس شخص سے جو رسول اللہ ﷺ کے فیصلے پر راضی نہ ہوا تھا، پوچھا: کیا ایسا ہی ہے؟ اس نے کہا: ہاں۔ تو عمر نے تلوار سے اسے قتل کر دیا۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 63907;
update hadith set translation_ur = 'اور جب قریش نے رسول اللہ ﷺ کو ﴿الرَّحْمَٰنَ﴾ کا ذکر کرتے سنا تو اس کا انکار کیا، تو اللہ نے ان کے بارے میں نازل فرمایا: ﴿وَهُمْ يَكْفُرُونَ بِالرَّحْمَٰنِ﴾ (اور وہ رحمٰن کا انکار کرتے ہیں)۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 64004;
update hadith set translation_ur = 'مجاہد رحمہ اللہ نے (آیت ﴿يَعْرِفُونَ نِعْمَتَ اللَّهِ ثُمَّ يُنكِرُونَهَا﴾ کے) معنی میں فرمایا: یہ آدمی کا یہ کہنا ہے: یہ میرا مال ہے جو مجھے اپنے باپ دادا سے ورثے میں ملا۔ اور عون بن عبد اللہ نے فرمایا: وہ کہتے ہیں: اگر فلاں نہ ہوتا تو ایسا نہ ہوتا۔ اور ابن قتیبہ نے فرمایا: وہ کہتے ہیں: یہ ہمارے معبودوں کی سفارش سے ہوا۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 64102;
update hadith set translation_ur = 'اور ابو العباس (ابن تیمیہ رحمہ اللہ) نے زید بن خالد رضی اللہ عنہ کی اس حدیث کے بعد — جس میں ہے: ”اللہ تعالیٰ نے فرمایا: میرے بندوں میں سے کچھ نے مجھ پر ایمان کی حالت میں صبح کی اور کچھ نے کفر کی حالت میں…“ اور جو پہلے گزر چکی — فرمایا: کتاب و سنت میں یہ بات بہت ہے کہ اللہ سبحانہ اس شخص کی مذمت کرتا ہے جو اس کی نعمت کو دوسرے کی طرف منسوب کرے اور اس کے ساتھ شریک ٹھہرائے۔ بعض سلف نے کہا: یہ ان کے اس قول کی طرح ہے: ہوا اچھی تھی اور ملاح ماہر تھا، اور اسی طرح کی وہ باتیں جو بہت سے لوگوں کی زبانوں پر جاری ہیں۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 64103;
update hadith set translation_ur = 'اور ابراہیم نخعی رحمہ اللہ سے مروی ہے کہ وہ اس بات کو ناپسند کرتے تھے کہ آدمی کہے: ”میں اللہ کی اور تمہاری پناہ مانگتا ہوں“، اور (اہلِ علم نے) کہا: یہ کہنا جائز ہے: ”میں اللہ کی پھر تمہاری پناہ مانگتا ہوں“۔ اور کہا: آدمی یوں کہے: ”اگر اللہ پھر فلاں نہ ہوتا“، اور یوں نہ کہو: ”اگر اللہ اور فلاں نہ ہوتے“۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 64206;
update hadith set translation_ur = 'ابن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا: ”اپنے باپ دادا کی قسم نہ کھاؤ۔ جو اللہ کی قسم کھائے وہ سچ بولے، اور جس کے لیے اللہ کی قسم کھائی جائے وہ (اس پر) راضی ہو جائے، اور جو راضی نہ ہو اس کا اللہ سے کوئی تعلق نہیں۔“ اسے ابن ماجہ نے حسن سند کے ساتھ روایت کیا ہے۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 64301;
update hadith set translation_ur = 'قتیلہ رضی اللہ عنہا سے روایت ہے کہ ایک یہودی نبی ﷺ کے پاس آیا اور کہا: تم لوگ شرک کرتے ہو، تم کہتے ہو: ”جو اللہ چاہے اور آپ چاہیں“، اور کہتے ہو: ”کعبہ کی قسم“۔ تو نبی ﷺ نے صحابہ کو حکم دیا کہ جب وہ قسم کھانا چاہیں تو کہیں: ”کعبہ کے رب کی قسم“، اور یہ کہیں: ”جو اللہ چاہے، پھر آپ چاہیں“۔ اسے نسائی نے روایت کیا اور صحیح کہا ہے۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 64401;
update hadith set translation_ur = 'اور ابن ماجہ میں عائشہ رضی اللہ عنہا کے اخیافی بھائی طفیل رضی اللہ عنہ سے روایت ہے، انہوں نے کہا: میں نے (خواب میں) دیکھا گویا میں یہودیوں کی ایک جماعت کے پاس آیا اور کہا: تم بہت اچھے لوگ ہوتے اگر تم یہ نہ کہتے: عزیر اللہ کے بیٹے ہیں! انہوں نے کہا: اور تم بھی بہت اچھے لوگ ہوتے اگر تم یہ نہ کہتے: جو اللہ چاہے اور محمد چاہیں۔ پھر میں عیسائیوں کی ایک جماعت کے پاس سے گزرا اور کہا: تم بہت اچھے لوگ ہوتے اگر تم یہ نہ کہتے: مسیح اللہ کے بیٹے ہیں! انہوں نے کہا: اور تم بھی بہت اچھے لوگ ہوتے اگر تم یہ نہ کہتے: جو اللہ چاہے اور محمد چاہیں۔ جب صبح ہوئی تو میں نے یہ خواب کچھ لوگوں کو بتایا، پھر نبی ﷺ کے پاس آ کر آپ کو بتایا۔ آپ نے پوچھا: ”کیا تم نے یہ کسی کو بتایا ہے؟“ میں نے کہا: ہاں۔ تو آپ نے اللہ کی حمد و ثنا کی، پھر فرمایا: ”اما بعد! طفیل نے ایک خواب دیکھا ہے جو اس نے تم میں سے بعض کو بتایا ہے، اور تم ایک ایسی بات کہتے تھے کہ فلاں فلاں چیز مجھے تمہیں اس سے روکنے میں مانع تھی؛ لہٰذا یہ نہ کہو: جو اللہ چاہے اور محمد چاہیں، بلکہ یہ کہو: جو اکیلا اللہ چاہے۔“', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 64403;
update hadith set translation_ur = 'اور صحیح (بخاری) میں ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا: ”اللہ تعالیٰ فرماتا ہے: ابن آدم مجھے تکلیف دیتا ہے، وہ زمانے کو برا کہتا ہے، حالانکہ زمانہ (کا مالک) میں ہوں، سارا معاملہ میرے ہاتھ میں ہے، میں ہی رات اور دن کو الٹتا پلٹتا ہوں۔“', explanation_ur = 'نبی ﷺ نے خبر دی کہ اللہ تعالیٰ حدیثِ قدسی میں فرماتا ہے: وہ انسان مجھے اذیت دیتا ہے اور میری تنقیص کرتا ہے جو مصیبتوں اور ناپسندیدہ حالات کے وقت زمانے کو برا بھلا کہتا ہے؛ کیونکہ اللہ سبحانہ ہی اکیلا تدبیر کرنے والا اور ہونے والے واقعات کو چلانے والا ہے۔ لہٰذا زمانے کو برا کہنا درحقیقت اللہ عزوجل کو برا کہنا ہے، جبکہ زمانہ تو ایک مسخر مخلوق ہے جس میں اللہ تعالیٰ کے حکم سے واقعات پیش آتے ہیں۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 64502;
update hadith set translation_ur = 'اور ایک روایت میں ہے: ”زمانے کو برا نہ کہو، کیونکہ (زمانے کو چلانے والا) اللہ ہی ہے۔“', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 64503;
update hadith set translation_ur = 'اور ایک روایت میں ہے: ”قیامت کے دن اللہ کے نزدیک سب سے زیادہ غضب کا شکار اور سب سے برا آدمی (وہ ہوگا جو شہنشاہ کہلائے)۔“ آپ کے فرمان ”اَخنع“ کا مطلب ہے: سب سے زیادہ ذلیل۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 64602;
update hadith set translation_ur = 'ابو شریح رضی اللہ عنہ سے روایت ہے کہ ان کی کنیت ”ابو الحکم“ تھی، تو نبی ﷺ نے ان سے فرمایا: ”حَکَم (فیصلہ کرنے والا) تو اللہ ہی ہے اور فیصلہ اسی کی طرف ہے۔“ انہوں نے کہا: میری قوم جب کسی بات میں اختلاف کرتی ہے تو میرے پاس آتی ہے اور میں ان کے درمیان فیصلہ کرتا ہوں تو دونوں فریق راضی ہو جاتے ہیں۔ آپ نے فرمایا: ”یہ کتنی اچھی بات ہے! تمہارے بچے کون کون ہیں؟“ میں نے کہا: شریح، مسلم اور عبد اللہ۔ فرمایا: ”ان میں بڑا کون ہے؟“ میں نے کہا: شریح۔ فرمایا: ”تو تم ابو شریح ہو۔“ اسے ابو داود وغیرہ نے روایت کیا ہے۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 64701;
update hadith set translation_ur = 'ابن عمر، محمد بن کعب، زید بن اسلم اور قتادہ سے روایت ہے — ان سب کی روایتیں ایک دوسرے میں شامل ہیں — کہ غزوۂ تبوک میں ایک آدمی نے کہا: ہم نے اپنے ان قاریوں جیسا کوئی نہیں دیکھا: سب سے زیادہ پیٹو، سب سے زیادہ جھوٹی زبان والے اور دشمن سے مقابلے کے وقت سب سے زیادہ بزدل۔ اس کی مراد رسول اللہ ﷺ اور آپ کے قاری صحابہ تھے۔ تو عوف بن مالک رضی اللہ عنہ نے اس سے کہا: تم نے جھوٹ کہا، بلکہ تم منافق ہو؛ میں ضرور رسول اللہ ﷺ کو بتاؤں گا۔ چنانچہ عوف آپ ﷺ کو بتانے گئے تو دیکھا کہ قرآن ان سے پہلے (وحی ہو کر) پہنچ چکا ہے۔ پھر وہ آدمی رسول اللہ ﷺ کے پاس آیا جبکہ آپ کوچ کر چکے تھے اور اپنی اونٹنی پر سوار ہو چکے تھے، اور کہنے لگا: اے اللہ کے رسول! ہم تو بس دل لگی اور ہنسی مذاق کر رہے تھے اور سواروں والی باتیں کر رہے تھے تاکہ راستے کی تھکن کم ہو۔ ابن عمر رضی اللہ عنہما فرماتے ہیں: گویا میں اسے دیکھ رہا ہوں کہ وہ رسول اللہ ﷺ کی اونٹنی کے پالان کی رسی سے لٹکا ہوا ہے، پتھر اس کے پاؤں کو ٹھوکریں لگا رہے ہیں اور وہ کہہ رہا ہے: ہم تو بس دل لگی اور کھیل کر رہے تھے۔ اور رسول اللہ ﷺ اس سے فرما رہے تھے: ﴿أَبِاللَّهِ وَآيَاتِهِ وَرَسُولِهِ كُنتُمْ تَسْتَهْزِئُونَ﴾ (کیا تم اللہ، اس کی آیتوں اور اس کے رسول کا مذاق اڑاتے تھے؟)، نہ اس کی طرف توجہ فرماتے اور نہ اس سے زیادہ کچھ کہتے۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 64802;
update hadith set translation_ur = 'مجاہد رحمہ اللہ نے (آیت ﴿لَيَقُولَنَّ هَٰذَا لِي﴾ کی تفسیر میں) فرمایا: (وہ کہتا ہے) یہ میرے عمل کی بدولت ہے اور میں اس کا حق دار ہوں۔ اور ابن عباس رضی اللہ عنہما نے فرمایا: اس کی مراد ہے: یہ میری اپنی طرف سے ہے۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 64902;
update hadith set translation_ur = 'اور اللہ کا فرمان: ﴿إِنَّمَا أُوتِيتُهُ عَلَىٰ عِلْمٍ﴾ (یہ تو مجھے علم کی بنا پر دیا گیا ہے)۔ قتادہ نے فرمایا: یعنی کمائی کے طریقوں کے بارے میں میرے اپنے علم کی بنا پر۔ اور دوسروں نے کہا: یعنی اللہ کے اس علم کی بنا پر کہ میں اس کا اہل ہوں۔ اور یہی مجاہد کے قول کا مطلب ہے: مجھے یہ میری بزرگی کی بنا پر دیا گیا ہے۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 64904;
update hadith set translation_ur = 'ابن حزم رحمہ اللہ نے فرمایا: (علماء) اس پر متفق ہیں کہ ہر وہ نام حرام ہے جس میں غیر اللہ کی بندگی ظاہر ہو، جیسے عبد عمرو، عبد الکعبہ اور اس جیسے نام، سوائے عبد المطلب کے۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 65002;
update hadith set translation_ur = 'اور ابن عباس رضی اللہ عنہما سے آیت کے معنی میں روایت ہے، انہوں نے فرمایا: جب آدم علیہ السلام نے حوا سے قربت کی تو وہ حاملہ ہو گئیں۔ ابلیس ان دونوں کے پاس آیا اور کہا: میں وہی ہوں جس نے تمہیں جنت سے نکلوایا، تم میری بات مانو ورنہ میں اس (بچے) کے لیے پہاڑی بکرے کے دو سینگ بنا دوں گا جو تمہارے پیٹ کو پھاڑ کر نکلے گا، اور میں یہ کروں گا اور وہ کروں گا — وہ انہیں ڈرا رہا تھا — اس کا نام عبد الحارث رکھو۔ انہوں نے اس کی بات ماننے سے انکار کیا تو بچہ مردہ پیدا ہوا۔ پھر وہ حاملہ ہوئیں تو وہ پھر آیا اور وہی بات کہی، انہوں نے پھر انکار کیا تو بچہ مردہ پیدا ہوا۔ پھر وہ حاملہ ہوئیں تو وہ آیا اور ان سے وہی بات کہی، تو اولاد کی محبت ان پر غالب آ گئی اور انہوں نے اس کا نام عبد الحارث رکھ دیا۔ یہی اللہ کا فرمان ہے: ﴿جَعَلَا لَهُ شُرَكَاءَ فِيمَا آتَاهُمَا﴾ (انہوں نے اس چیز میں جو اللہ نے انہیں دی تھی، اس کے شریک ٹھہرا دیے)۔ اسے ابن ابی حاتم نے روایت کیا ہے۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 65003;
update hadith set translation_ur = 'اور انہی (ابن ابی حاتم) کی روایت میں صحیح سند سے قتادہ سے ہے، انہوں نے فرمایا: (یہ شرک) اس کی اطاعت میں شراکت تھی، اس کی عبادت میں نہیں۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 65004;
update hadith set translation_ur = 'اور انہی کی روایت میں صحیح سند سے مجاہد سے اللہ کے فرمان ﴿لَئِنْ آتَيْتَنَا صَالِحًا﴾ (اگر تو نے ہمیں تندرست بچہ دیا) کے بارے میں ہے کہ انہوں نے فرمایا: انہیں ڈر تھا کہ کہیں وہ انسان (کی شکل میں) نہ ہو۔ اور یہی معنی حسن، سعید اور دوسروں سے بھی ذکر کیا ہے۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 65005;
update hadith set translation_ur = 'ابن ابی حاتم نے ابن عباس رضی اللہ عنہما سے آیت ﴿يُلْحِدُونَ فِي أَسْمَائِهِ﴾ (جو اس کے ناموں میں کج روی کرتے ہیں) کے بارے میں ذکر کیا: یعنی شرک کرتے ہیں۔ اور انہی سے روایت ہے: انہوں نے ”اللات“ کا نام ”الالٰہ“ سے اور ”العزّیٰ“ کا نام ”العزیز“ سے بنایا۔ اور اعمش سے روایت ہے: وہ اس کے ناموں میں وہ چیز داخل کرتے ہیں جو ان میں سے نہیں۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 65102;
update hadith set translation_ur = 'اور مسلم کی روایت میں ہے: ”اور وہ رغبت (مانگنے) کو بڑا کرے، کیونکہ اللہ کے لیے کوئی بھی چیز جو وہ عطا کرے، بڑی نہیں۔“', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 65302;
update hadith set translation_ur = 'صحیح (بخاری) میں ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا: ”تم میں سے کوئی (کسی کے غلام سے) یہ نہ کہے: اپنے رب کو کھانا کھلاؤ، اپنے رب کو وضو کراؤ؛ بلکہ کہے: میرے سردار، میرے آقا۔ اور تم میں سے کوئی یہ نہ کہے: میرا بندہ، میری بندی؛ بلکہ کہے: میرا جوان، میری جوان (خادمہ)، میرا لڑکا۔“', explanation_ur = 'نبی ﷺ نے منع فرمایا کہ کوئی کسی دوسرے کے غلام سے کہے: اپنے رب کو پلاؤ، اپنے رب کو کھلاؤ، اپنے رب کو وضو کراؤ؛ بلکہ کہے: اپنے سردار کو۔ اس ممانعت کا سبب یہ ہے کہ حقیقی ربوبیت اللہ تعالیٰ ہی کے لیے ہے؛ کیونکہ رب وہ ہے جو مالک اور ہر چیز کا نگہبان ہو، اور یہ حقیقتاً صرف اللہ کے لیے ہے۔ سید اور رب میں فرق اس لیے کیا کہ ”رب“ بالاتفاق اللہ کے ناموں میں سے ہے، جبکہ ”سید“ کے اللہ کا نام ہونے میں اختلاف ہے، اور اگر اسے اللہ کا نام مان بھی لیں تو وہ ”رب“ جیسا مشہور اور مستعمل نہیں؛ یوں فرق حاصل ہو جاتا ہے۔ اور کوئی اپنے غلام کو ”میرا بندہ، میری بندی“ نہ کہے، بلکہ ”میرا جوان، میری جوان (خادمہ)، میرا لڑکا“ کہے؛ کیونکہ حقیقی بندگی کا مستحق صرف اللہ تعالیٰ ہے، اور اس لفظ میں ایسی تعظیم ہے جو مخلوق کے لائق نہیں۔ چنانچہ آپ ﷺ نے ایسے الفاظ کی رہنمائی فرمائی جو مطلوبہ معنی ادا کریں اور بڑائی کے اظہار سے محفوظ ہوں؛ یہ الفاظ آزاد اور غلام دونوں کے لیے بولے جاتے ہیں، البتہ نسبت سے اختصاص ظاہر ہوتا ہے۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 65401;
update hadith set translation_ur = 'ابن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا: ”جو اللہ کا واسطہ دے کر پناہ مانگے اسے پناہ دو، جو اللہ کے نام پر سوال کرے اسے دو، جو تمہیں دعوت دے اسے قبول کرو، اور جو تمہارے ساتھ کوئی بھلائی کرے اس کا بدلہ دو؛ اگر بدلہ دینے کو کچھ نہ پاؤ تو اس کے لیے اتنی دعا کرو کہ تمہیں یقین ہو جائے کہ تم نے اس کا بدلہ چکا دیا ہے۔“ اسے ابو داود اور نسائی نے صحیح سند کے ساتھ روایت کیا ہے۔', explanation_ur = 'رسول اللہ ﷺ نے فرمایا: تم میں سے جو کوئی اللہ کا واسطہ دے کر یہ مانگے کہ تم اس سے اپنا یا کسی اور کا شر دور کرو — مثلاً کہے: اے فلاں! تمہیں اللہ کا واسطہ، یا میں تم سے اللہ کے نام پر مانگتا ہوں کہ مجھ سے اپنا یا فلاں کا شر دور کرو، یا مجھے فلاں سے بچاؤ — تو اللہ کے نام کی تعظیم میں اس کی بات مانو اور اس کی حفاظت کرو۔ اور جو اللہ کے نام پر سوال کرے، اللہ کے نام کی تعظیم اور اس کے بندوں پر شفقت کرتے ہوئے اسے دو۔ اور جو تمہیں کھانے کی دعوت دے اسے قبول کرو، یہ بھی ایک مسلمان کا دوسرے مسلمان پر حق ہے۔ اور جو تمہارے ساتھ قول یا عمل سے بھلائی کرے، تم بھی اس کے ساتھ ویسی ہی بھلائی کرو؛ اگر برابر کا بدلہ نہ دے سکو تو اس کے لیے دعا کر کے بدلہ دو، کہ اللہ تعالیٰ سے مانگو کہ وہ اسے اس کی نیکی کا بدلہ دے، اور بار بار اور خوب دعا کرو یہاں تک کہ تمہیں گمان ہو جائے کہ تمہاری دعا کی قبولیت سے تم نے اس کا بدلہ چکا دیا۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 65501;
update hadith set translation_ur = 'جابر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا: ”اللہ کے چہرے (کے واسطے) سے جنت کے سوا کچھ نہ مانگا جائے۔“ اسے ابو داود نے روایت کیا ہے۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 65601;
update hadith set translation_ur = 'صحیح (مسلم) میں ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا: ”جو چیز تمہیں فائدہ دے اس کی حرص کرو اور اللہ سے مدد مانگو اور عاجز نہ بنو۔ اگر تمہیں کوئی مصیبت پہنچے تو یہ نہ کہو: اگر میں ایسا کرتا تو ایسا ایسا ہو جاتا، بلکہ کہو: اللہ کی تقدیر ہے اور اس نے جو چاہا کیا؛ کیونکہ ”اگر“ شیطان کے کام کا دروازہ کھولتا ہے۔“', explanation_ur = 'چونکہ اسلام دنیا کو آباد کرنے اور معاشرے کی اصلاح کی دعوت دیتا ہے، اس لیے رسول اللہ ﷺ نے ہر مسلمان کو سنجیدہ محنت اور حصول کا حکم دیا، اس حال میں کہ وہ اس کے لیے اللہ عزوجل سے مدد مانگے اور عاجزی (کاہلی) اور اس کے اسباب سے بچے؛ اور جب مطلوب چیز ہاتھ سے نکل جائے تو اپنے اوپر ملامت اور پچھتاوے کا دروازہ نہ کھولے، کیونکہ یہ اسے ناراضی اور بے صبری کی طرف لے جاتا ہے؛ بلکہ اپنا معاملہ اللہ کے سپرد کر دے اور قضا و قدر سے اپنے دل کو تسلی دے، تاکہ شیطان کو اس پر کوئی راستہ نہ ملے کہ وہ اسے بھڑکائے اور اللہ عزوجل اور اس کی قضا و قدر پر اس کے ایمان کو متزلزل کرے۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 65703;
update hadith set translation_ur = 'ابن القیم رحمہ اللہ نے پہلی آیت کے بارے میں فرمایا: اس (برے) گمان کی تفسیر یہ کی گئی ہے کہ اللہ سبحانہ اپنے رسول کی مدد نہیں کرے گا اور آپ کا معاملہ مٹ جائے گا۔ اور اس کی تفسیر ان کے اس گمان سے بھی کی گئی کہ جو کچھ انہیں پہنچا وہ اللہ کی تقدیر اور حکمت سے نہیں تھا۔ گویا اس کی تفسیر حکمت کے انکار، تقدیر کے انکار، اور اس بات کے انکار سے کی گئی کہ اللہ اپنے رسول کا معاملہ پورا کرے گا اور اسے تمام ادیان پر غالب کرے گا۔ یہی وہ برا گمان ہے جو مشرکین اور منافقین نے ”سورۃ الفتح“ میں کیا۔ اور یہ برا گمان اس لیے تھا کہ یہ ایسا گمان ہے جو اللہ سبحانہ کے لائق نہیں، نہ اس کی حکمت، حمد اور سچے وعدے کے شایانِ شان ہے۔ پس جس نے یہ گمان کیا کہ وہ باطل کو حق پر ایسا مستقل غلبہ دے گا کہ حق مٹ جائے، یا اس بات کا انکار کیا کہ جو کچھ ہوا وہ اس کی قضا و قدر سے ہوا، یا اس بات کا انکار کیا کہ اس نے اسے کسی کامل حکمت سے مقدر کیا جس پر وہ حمد کا مستحق ہے، بلکہ یہ دعویٰ کیا کہ یہ محض مشیت سے ہوا، تو ﴿ذَٰلِكَ ظَنُّ الَّذِينَ كَفَرُوا ۚ فَوَيْلٌ لِّلَّذِينَ كَفَرُوا مِنَ النَّارِ﴾ (یہ کافروں کا گمان ہے، سو کافروں کے لیے آگ کی ہلاکت ہے)۔ اکثر لوگ اپنے بارے میں اور دوسروں کے ساتھ اللہ کے معاملے کے بارے میں اللہ سے برا گمان رکھتے ہیں، اور اس سے صرف وہی بچتا ہے جس نے اللہ کو، اس کے ناموں اور صفات کو، اور اس کی حکمت و حمد کے تقاضوں کو پہچانا۔ لہٰذا اپنے خیرخواہ عقل مند کو چاہیے کہ اس پر توجہ دے، اللہ سے توبہ کرے اور اپنے رب سے برے گمان پر اس سے مغفرت مانگے۔ اگر تم جس کو بھی ٹٹولو گے تو اس کے پاس تقدیر پر اعتراض اور اس کی ملامت پاؤ گے کہ ایسا ایسا ہونا چاہیے تھا؛ کوئی کم اور کوئی زیادہ۔ اور اپنے آپ کو ٹٹولو: کیا تم اس سے محفوظ ہو؟ ”اگر تم اس سے بچ گئے تو ایک بڑی مصیبت سے بچ گئے، ورنہ میں تمہیں بچنے والا نہیں سمجھتا“۔ ان کا کلام ختم ہوا۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 65903;
update hadith set translation_ur = 'اور ابن عمر رضی اللہ عنہما نے فرمایا: اس ذات کی قسم جس کے ہاتھ میں ابن عمر کی جان ہے! اگر ان (منکرینِ تقدیر) میں سے کسی کے پاس احد پہاڑ کے برابر سونا ہو اور وہ اسے اللہ کی راہ میں خرچ کر دے تو اللہ اس سے قبول نہیں کرے گا جب تک کہ وہ تقدیر پر ایمان نہ لائے۔ پھر انہوں نے نبی ﷺ کے اس فرمان سے دلیل دی: ”ایمان یہ ہے کہ تم اللہ، اس کے فرشتوں، اس کی کتابوں، اس کے رسولوں اور آخرت کے دن پر ایمان لاؤ، اور اچھی اور بری تقدیر پر ایمان لاؤ۔“ اسے مسلم نے روایت کیا ہے۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 66001;
update hadith set translation_ur = 'اور امام احمد کی ایک روایت میں ہے: ”اللہ تعالیٰ نے سب سے پہلے قلم کو پیدا کیا تو اس سے فرمایا: لکھ؛ تو وہ اسی وقت قیامت تک ہونے والی ہر چیز کو لکھتا چلا گیا۔“', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 66003;
update hadith set translation_ur = 'اور ابن وہب کی ایک روایت میں ہے کہ رسول اللہ ﷺ نے فرمایا: ”جو اچھی اور بری تقدیر پر ایمان نہ لائے، اللہ اسے آگ میں جلائے گا۔“', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 66004;
update hadith set translation_ur = 'ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا: ”اللہ تعالیٰ فرماتا ہے: اس سے بڑا ظالم کون ہوگا جو میری تخلیق کی طرح تخلیق کرنے چلا! تو وہ ایک چیونٹی بنا کر دکھائیں، یا ایک دانہ بنا کر دکھائیں، یا جَو کا ایک دانہ بنا کر دکھائیں۔“ اسے بخاری و مسلم نے روایت کیا ہے۔', explanation_ur = 'اس جلیل القدر تابعی نے ذکر کیا کہ وہ ابو ہریرہ رضی اللہ عنہ کے ساتھ ایک گھر میں داخل ہوئے تو اس کے اوپر والے حصے میں ایک مصور کو تصویریں بناتے دیکھا — اور مراد جانداروں کی تصویریں ہیں، جیسے انسان، پرندے اور چوپائے — تو انہوں نے نبی ﷺ سے اس قسم کی تصویر کشی کی حرمت کے بارے میں ایک حدیث روایت کی، اور یہ حدیثِ قدسی ہے جیسا کہ دوسری روایات سے معلوم ہوتا ہے۔ اللہ تعالیٰ فرماتا ہے: اس سے بڑا ظالم کوئی نہیں جو اللہ تعالیٰ کی تخلیق جیسی تخلیق کرنے کی کوشش کرے۔ اس سے معلوم ہوا کہ تصویر جتنی زیادہ مطابقت رکھے، اتنی ہی زیادہ حرام ہے۔ لہٰذا جانداروں کی ویڈیو بنانے والا خطرے میں ہے؛ کیونکہ اس کا معاملہ دو اقوال کے درمیان ہے: ایک جواز کا، اس بنا پر کہ یہ عمل تصویر کی حرمت والی نصوص میں داخل نہیں، اور دوسرا حرمت کا، اس بنا پر کہ یہ ان میں داخل ہے؛ اور یقینی طور پر معلوم نہیں ہوگا کہ کون سا قول زیادہ صحیح ہے یہاں تک کہ وہ اپنے عمل کے ساتھ رب العالمین سبحانہ و تعالیٰ کے حضور پہنچے؛ تو پھر خطرہ مول لینے کی کیا ضرورت؟', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 66101;
update hadith set translation_ur = 'اور بخاری و مسلم میں ابن عباس رضی اللہ عنہما سے روایت ہے کہ میں نے رسول اللہ ﷺ کو فرماتے سنا: ”ہر تصویر بنانے والا جہنم میں ہوگا، اس کی بنائی ہوئی ہر تصویر کے بدلے ایک جان بنائی جائے گی جس کے ذریعے اسے جہنم میں عذاب دیا جائے گا۔“', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 66103;
update hadith set translation_ur = 'اور بخاری و مسلم میں انہی سے مرفوعاً روایت ہے: ”جس نے دنیا میں کوئی تصویر بنائی، اسے (قیامت کے دن) مجبور کیا جائے گا کہ اس میں روح پھونکے، اور وہ روح نہیں پھونک سکے گا۔“', explanation_ur = 'ایک آدمی عبد اللہ بن عباس رضی اللہ عنہما کے پاس آیا اور کہا: اے ابو عباس! میں اپنے ہاتھ کی کمائی سے گزارا کرتا ہوں اور یہ تصویریں اور مجسمے بناتا ہوں۔ ابن عباس نے فرمایا: میں تمہیں وہی بتاؤں گا جو میں نے نبی ﷺ سے سنا ہے؛ میں نے آپ کو فرماتے سنا: جس نے کوئی تصویر بنائی، اللہ اسے اس کے ذریعے عذاب دے گا اور اس سے مطالبہ کرے گا کہ اس میں روح پھونکے، اور وہ کبھی اس میں روح نہیں پھونک سکے گا، لہٰذا اللہ اسے ہمیشہ عذاب دیتا رہے گا۔ یہ سن کر وہ آدمی گھبرا گیا، خوف سے بھر گیا، اس کا سانس پھول گیا اور سینہ تنگ ہو گیا اور اس کا چہرہ زرد پڑ گیا۔ تو ابن عباس نے اس سے فرمایا: تمہارا بھلا ہو! اگر تم یہ کام کرنے پر ہی مُصر ہو تو درختوں اور ہر اس چیز کی تصویریں بناؤ جس میں روح نہیں؛ کیونکہ جس چیز میں روح نہ ہو اس کی تصویر بنانے میں کوئی حرج نہیں۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 66104;
update hadith set translation_ur = 'اور صحیحین میں عمران بن حصین رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا: ”میری امت کا بہترین زمانہ میرا زمانہ ہے، پھر وہ لوگ جو ان کے بعد آئیں گے، پھر وہ جو ان کے بعد آئیں گے۔“ عمران کہتے ہیں: مجھے یاد نہیں کہ آپ نے اپنے زمانے کے بعد دو زمانوں کا ذکر کیا یا تین کا۔ ”پھر تمہارے بعد ایسے لوگ آئیں گے جو گواہی دیں گے حالانکہ ان سے گواہی طلب نہیں کی جائے گی، خیانت کریں گے اور امانت دار نہیں ہوں گے، نذر مانیں گے اور پوری نہیں کریں گے، اور ان میں موٹاپا ظاہر ہوگا۔“', explanation_ur = 'نبی ﷺ نے خبر دی کہ ایک زمانے میں اکٹھے رہنے والے لوگوں کا بہترین طبقہ وہ ہے جس میں رسول اللہ ﷺ اور آپ کے صحابہ تھے، پھر ان کے بعد وہ مومن جنہوں نے صحابہ کو پایا مگر رسول اللہ ﷺ کو نہیں پایا (تابعین)، پھر ان کے بعد والے یعنی تبع تابعین؛ اور صحابی کو چوتھے زمانے کے ذکر میں تردد ہوا۔ پھر آپ ﷺ نے فرمایا: ان کے بعد ایسے لوگ ہوں گے جو خیانت کریں گے اور لوگ ان پر اعتماد نہیں کریں گے، گواہی طلب کیے جانے سے پہلے ہی گواہی دیں گے، نذر مانیں گے اور پوری نہیں کریں گے، اور کھانے پینے میں اتنی وسعت اختیار کریں گے کہ ان میں موٹاپا ظاہر ہو جائے گا۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 66204;
update hadith set translation_ur = 'اور اسی میں ابن مسعود رضی اللہ عنہ سے روایت ہے کہ نبی ﷺ نے فرمایا: ”بہترین لوگ میرے زمانے کے ہیں، پھر وہ جو ان کے بعد آئیں گے، پھر وہ جو ان کے بعد آئیں گے۔ پھر ایسے لوگ آئیں گے جن میں سے کسی کی گواہی اس کی قسم سے پہلے اور قسم اس کی گواہی سے پہلے ہوگی۔“ ابراہیم نخعی نے کہا: جب ہم چھوٹے تھے تو (ہمارے بڑے) ہمیں گواہی اور عہد (میں جلد بازی) پر مارا کرتے تھے۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 66205;
update hadith set translation_ur = 'اور ابو ہریرہ رضی اللہ عنہ کی حدیث میں ہے کہ (یہ بات) کہنے والا ایک عبادت گزار آدمی تھا۔ ابو ہریرہ نے فرمایا: اس نے ایک ایسی بات کہی جس نے اس کی دنیا اور آخرت برباد کر دی۔', explanation_ur = 'ابو ہریرہ رضی اللہ عنہ روایت کرتے ہیں کہ نبی ﷺ نے فرمایا: بنی اسرائیل میں دو آدمی اللہ کی خاطر بھائی بنے ہوئے تھے؛ ان میں سے ایک سے بہت گناہ ہوتے تھے اور دوسرا اللہ کی عبادت میں لگا رہتا تھا۔ عبادت گزار اپنے بھائی کو گناہ پر اصرار کرتے دیکھتا تو کہتا: بھائی! یہ گناہ چھوڑ دو۔ ایک دن اس نے اسے حسبِ عادت کسی گناہ پر پایا تو کہا: گناہ سے رک جاؤ اور اسے چھوڑ دو۔ گناہ گار نے جواب دیا: مجھے اور میرے رب کو چھوڑ دو، جو گناہ بخشتا اور توبہ قبول کرتا ہے؛ کیا اللہ نے تمہیں مجھ پر نگران بنا کر بھیجا ہے کہ میرے اقوال و افعال کی نگرانی کرو؟ تو اس نے کہا: اللہ کی قسم! اللہ تمہیں کبھی نہیں بخشے گا، یا کہا: اللہ تمہیں کبھی جنت میں داخل نہیں کرے گا۔ پھر دونوں فوت ہو گئے اور حساب کے لیے رب العالمین کے سامنے جمع ہوئے۔ تو اللہ عزوجل نے اس عبادت گزار سے فرمایا: جب تم نے اس سے وہ بات کہی تو کیا تم مجھے جانتے تھے کہ میں اسے نہیں بخشوں گا؟ — حالانکہ وہ بخشنے والا مہربان ہے اور کوئی اس کے علم کا احاطہ نہیں کر سکتا سوائے اس کے جو وہ چاہے — یا کیا تم میرے اختیار کی چیز پر قادر تھے کہ میں اسے جنت میں داخل نہ کروں؟ اور گناہ گار سے فرمایا: جاؤ، میری اس رحمت سے جنت میں داخل ہو جاؤ جو ہر چیز پر وسیع ہے۔ اور عبادت گزار کے بارے میں فرمایا: اسے آگ کی طرف لے جاؤ۔ ابو ہریرہ نے فرمایا: اس ذات کی قسم جس کے ہاتھ میں میری جان ہے! اس عبادت گزار نے ایسی بات کہی جس نے اس کی دنیا اور آخرت برباد کر دی؛ یہ جہالت اور اپنی بزرگی، نصیب اور مرتبے کی بنا پر اللہ پر ناز کرنے کا نتیجہ ہے۔ اس میں اہلِ سنت کے مذہب کی دلیل ہے کہ اللہ چاہے تو مومن کے گناہ بغیر توبہ کے بھی بخش دیتا ہے۔ اور ظاہر یہ ہے کہ اس عبادت گزار نے قطعی طور پر یہ فیصلہ کر دیا کہ اللہ گناہ گار کو نہیں بخشے گا، گویا اس نے اللہ کے علم پر حکم لگایا اور اس پر پابندی لگائی، حالانکہ اسے اس کا کوئی حق نہیں تھا۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 66402;
update hadith set translation_ur = 'جبیر بن مطعم رضی اللہ عنہ سے روایت ہے کہ ایک دیہاتی نبی ﷺ کے پاس آیا اور کہا: اے اللہ کے رسول! جانیں تھک گئیں، بال بچے بھوکے ہیں اور مال ہلاک ہو گئے، لہٰذا آپ ہمارے لیے اپنے رب سے بارش کی دعا کیجیے، ہم آپ کے پاس اللہ کو سفارشی بناتے ہیں اور اللہ کے پاس آپ کو۔ تو نبی ﷺ نے فرمایا: ”سبحان اللہ، سبحان اللہ!“ آپ مسلسل سبحان اللہ کہتے رہے یہاں تک کہ اس کا اثر آپ کے صحابہ کے چہروں پر دکھائی دینے لگا۔ پھر فرمایا: ”تمہارا برا ہو! کیا تم جانتے ہو اللہ کون ہے؟ اللہ کی شان اس سے کہیں بلند ہے، اللہ کو اس کی مخلوق میں سے کسی کے پاس سفارشی نہیں بنایا جاتا…“ اور پوری حدیث ذکر کی۔ اسے ابو داود نے روایت کیا ہے۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 66501;
update hadith set translation_ur = 'انس رضی اللہ عنہ سے روایت ہے کہ کچھ لوگوں نے کہا: اے اللہ کے رسول! اے ہم میں سب سے بہتر اور ہم میں سب سے بہتر کے بیٹے! اے ہمارے سردار اور ہمارے سردار کے بیٹے! تو آپ نے فرمایا: ”اے لوگو! اپنی (عام) بات کہو، اور شیطان تمہیں بہکا نہ دے۔ میں محمد ہوں، اللہ کا بندہ اور اس کا رسول۔ مجھے یہ پسند نہیں کہ تم مجھے میرے اس مرتبے سے بڑھا دو جس پر اللہ عزوجل نے مجھے رکھا ہے۔“ اسے نسائی نے جید سند کے ساتھ روایت کیا ہے۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 66602;
update hadith set translation_ur = 'اور مسلم کی ایک روایت میں ہے: ”اور پہاڑوں اور درختوں کو ایک انگلی پر (رکھے گا)، پھر انہیں ہلائے گا اور فرمائے گا: میں ہی بادشاہ ہوں، میں ہی اللہ ہوں۔“', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 66703;
update hadith set translation_ur = 'اور بخاری کی ایک روایت میں ہے: ”وہ آسمانوں کو ایک انگلی پر، پانی اور مٹی کو ایک انگلی پر، اور باقی ساری مخلوق کو ایک انگلی پر رکھے گا۔“ اسے بخاری و مسلم نے روایت کیا ہے۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 66704;
update hadith set translation_ur = 'اور ابن جریر نے فرمایا: مجھ سے یونس نے بیان کیا، ہمیں ابن وہب نے خبر دی، انہوں نے کہا: ابن زید نے کہا: مجھ سے میرے والد نے بیان کیا کہ رسول اللہ ﷺ نے فرمایا: ”ساتوں آسمان کرسی کے مقابلے میں ایسے ہیں جیسے سات درہم کسی ڈھال میں ڈال دیے گئے ہوں۔“', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 66707;
update hadith set translation_ur = 'اور ابن مسعود رضی اللہ عنہ نے فرمایا: آسمانِ دنیا اور اس کے بعد والے آسمان کے درمیان پانچ سو سال کا فاصلہ ہے، اور ہر دو آسمانوں کے درمیان پانچ سو سال کا فاصلہ ہے، اور ساتویں آسمان اور کرسی کے درمیان پانچ سو سال کا فاصلہ ہے، اور کرسی اور پانی کے درمیان پانچ سو سال کا فاصلہ ہے، اور عرش پانی کے اوپر ہے، اور اللہ عرش کے اوپر ہے، تمہارے اعمال میں سے کوئی چیز اس سے پوشیدہ نہیں۔ اسے ابن مہدی نے حماد بن سلمہ سے، انہوں نے عاصم سے، انہوں نے زر سے اور انہوں نے عبد اللہ (بن مسعود) سے روایت کیا۔ اور مسعودی نے اسی طرح عاصم سے، انہوں نے ابو وائل سے اور انہوں نے عبد اللہ سے روایت کیا۔ یہ بات حافظ ذہبی رحمہ اللہ نے کہی، اور فرمایا: اس کی کئی سندیں ہیں۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 66709;
update hadith set translation_ur = 'اور عباس بن عبد المطلب رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا: ”کیا تم جانتے ہو آسمان اور زمین کے درمیان کتنا فاصلہ ہے؟“ ہم نے کہا: اللہ اور اس کا رسول بہتر جانتے ہیں۔ فرمایا: ”ان دونوں کے درمیان پانچ سو سال کی مسافت ہے، اور ہر آسمان سے دوسرے آسمان تک پانچ سو سال کی مسافت ہے، اور ہر آسمان کی موٹائی پانچ سو سال کی مسافت ہے، اور ساتویں آسمان اور عرش کے درمیان ایک سمندر ہے جس کے نیچے اور اوپر کے درمیان اتنا فاصلہ ہے جتنا آسمان اور زمین کے درمیان، اور اللہ تعالیٰ اس سب کے اوپر ہے، اور بنی آدم کے اعمال میں سے کوئی چیز اس سے پوشیدہ نہیں۔“ اسے ابو داود وغیرہ نے روایت کیا ہے۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 66710;
update hadith set translation_ur = 'عوف بن مالک اشجعی رضی اللہ عنہ سے روایت ہے، انہوں نے کہا: ہم جاہلیت میں دم (رقیہ) کیا کرتے تھے، تو ہم نے کہا: اے اللہ کے رسول! آپ اس کے بارے میں کیا فرماتے ہیں؟ آپ نے فرمایا: ”اپنے دم مجھ پر پیش کرو، دم میں کوئی حرج نہیں جب تک اس میں شرک نہ ہو۔“ اور ابو داود کے الفاظ ہیں: ”اپنے دم مجھ پر پیش کرو، دم میں کوئی حرج نہیں جب تک وہ شرک نہ ہوں۔“', explanation_ur = 'عوف بن مالک اشجعی رضی اللہ عنہ نے کہا: ہم اسلام سے پہلے جاہلیت میں دم (رقیہ) کیا کرتے تھے، تو ہم نے نبی ﷺ سے پوچھا: جو دم ہم جاہلیت میں کیا کرتے تھے ان کے بارے میں آپ کی کیا رائے ہے؟ آپ ﷺ نے فرمایا: اپنے دم مجھے دکھاؤ، دم میں کوئی حرج نہیں جب تک اس میں شرک نہ ہو۔ لہٰذا دم جائز ہے جب وہ سمجھ میں آنے والے الفاظ میں ہو اور اس میں شرک نہ ہو، اور سب سے افضل اور مفید وہ ہے جو اللہ تعالیٰ کے ناموں، اس کے کلام اور اس کے رسول ﷺ کے کلام سے ہو؛ اور یہ عقیدہ رکھا جائے کہ دم بذاتِ خود اثر نہیں کرتا بلکہ اللہ تعالیٰ کے حکم سے اثر کرتا ہے۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 70101;
update hadith set translation_ur = 'انس رضی اللہ عنہ سے روایت ہے، انہوں نے کہا: رسول اللہ ﷺ نے نظرِ بد، زہریلے ڈنک اور ”نملہ“ (پہلو کے پھوڑے/پھنسیوں) کے لیے دم کرنے کی اجازت دی۔', explanation_ur = 'نبی ﷺ نے تین چیزوں میں دم کی اجازت دی: پہلی: نظرِ بد، یعنی کوئی شخص کسی چیز کو دیکھ کر اس پر تعجب کرے اور اللہ کا ذکر نہ کرے تو اس کے تعجب سے اس چیز کو نقصان پہنچ جائے۔ دوسری: زہر سے دم، جب کوئی زہریلا جانور جیسے سانپ یا بچھو ڈس لے۔ تیسری: وہ پھوڑے پھنسیاں جو پہلو وغیرہ میں نکلتے ہیں۔ اس کا مطلب یہ نہیں کہ دم کا جواز انہی تین چیزوں کے ساتھ خاص ہے، بلکہ آپ ﷺ سے ان تین کے بارے میں پوچھا گیا تو آپ نے اجازت دی، اور آپ ﷺ نے ان کے علاوہ میں بھی دم کیا ہے۔ اور اجازت دینے میں دلیل ہے کہ پہلے دم ممنوع تھا؛ آپ نے مطلقاً اس لیے منع فرمایا تھا کہ جاہلیت میں لوگ شرکیہ اور ناقابلِ فہم الفاظ سے دم کرتے تھے۔ پھر دم جائز ہو گیا جب وہ سمجھ میں آنے والے الفاظ میں ہو اور اس میں نہ شرک ہو نہ کوئی ممنوع چیز، اور سب سے افضل اور مفید وہ ہے جو اللہ تعالیٰ کے ناموں، اس کے کلام اور اس کے رسول ﷺ کے کلام سے ہو۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 70102;
update hadith set translation_ur = 'ابن عباس رضی اللہ عنہما سے روایت ہے کہ نبی ﷺ کے کچھ صحابہ ایک پانی (والی بستی) کے پاس سے گزرے جہاں ایک آدمی کو (بچھو یا سانپ نے) ڈس لیا تھا۔ پانی والوں میں سے ایک آدمی ان کے پاس آیا اور کہا: کیا تم میں کوئی دم کرنے والا ہے؟ یہاں ایک آدمی کو ڈس لیا گیا ہے۔ تو ان میں سے ایک صاحب گئے اور چند بکریوں کے عوض سورۂ فاتحہ پڑھ کر دم کیا تو وہ ٹھیک ہو گیا۔ وہ بکریاں لے کر اپنے ساتھیوں کے پاس آئے تو انہوں نے اسے ناپسند کیا اور کہا: تم نے اللہ کی کتاب پر اجرت لی! یہاں تک کہ وہ مدینہ پہنچے اور عرض کیا: اے اللہ کے رسول! انہوں نے اللہ کی کتاب پر اجرت لی ہے۔ تو رسول اللہ ﷺ نے فرمایا: ”جن چیزوں پر تم اجرت لیتے ہو ان میں سب سے زیادہ حق دار اللہ کی کتاب ہے۔“', explanation_ur = 'نبی ﷺ کے صحابہ کی ایک جماعت ایک جگہ اتری جہاں پانی تھا۔ وہاں کے رہنے والوں میں ایک آدمی کو بچھو نے ڈس لیا تھا — یا ”سلیم“ یعنی بیمار تھا (راوی کو شک ہے)، اور یہ اسی معنی میں ہے، نیک فال کے طور پر ڈسے ہوئے کو ”سلیم“ (سلامت) کہا جاتا ہے۔ وہاں کے ایک آدمی نے صحابہ سے پوچھا: کیا تم میں کوئی دم کرنے والا ہے؟ اور انہیں ڈسے ہوئے آدمی کے بارے میں بتایا۔ تو صحابہ میں سے ایک صاحب گئے اور دم کی اجرت میں کچھ بکریاں لینے کی شرط پر اس پر سورۂ فاتحہ پڑھی، تو ڈسا ہوا آدمی شفا پا گیا۔ دم کرنے والے صحابی بکریاں لے کر ساتھیوں کے پاس آئے تو انہوں نے انہیں لینا ناپسند کیا اور کہا: تم نے قرآن پر اجرت لی ہے! یہاں تک کہ وہ مدینہ پہنچے اور نبی ﷺ سے اس کے بارے میں پوچھا، تو آپ ﷺ نے فرمایا: جن چیزوں پر تم اجرت لیتے ہو ان میں سب سے بہتر اللہ کی کتاب ہے۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 70207;
update hadith set translation_ur = 'عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ ﷺ جب بیمار ہوتے تو معوذات (قل اعوذ والی سورتیں) پڑھ کر اپنے اوپر پھونکتے اور اپنا ہاتھ (جسم پر) پھیرتے۔ پھر جب آپ اس بیماری میں مبتلا ہوئے جس میں آپ کی وفات ہوئی تو میں وہی معوذات پڑھ کر آپ پر پھونکنے لگی جو آپ پڑھ کر پھونکا کرتے تھے، اور نبی ﷺ کا ہاتھ آپ (کے جسم) پر پھیرتی تھی۔', explanation_ur = 'عائشہ رضی اللہ عنہا نے بتایا کہ نبی ﷺ جب بیمار ہوتے تو ﴿قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ﴾ اور ﴿قُلْ أَعُوذُ بِرَبِّ النَّاسِ﴾ پڑھتے، پھر اپنے ہاتھ پر منہ سے ہلکی سی تھوک کے ساتھ پھونک مارتے اور ہاتھ اپنے جسم پر پھیرتے۔ پھر جب آپ اس بیماری میں مبتلا ہوئے جس میں آپ کی وفات ہوئی تو عائشہ رضی اللہ عنہا وہی معوذات پڑھتیں جو نبی ﷺ پڑھا کرتے تھے، پھر بغیر تھوک کے یا ہلکی تھوک کے ساتھ پھونکتیں اور برکت کے لیے نبی ﷺ ہی کا ہاتھ آپ کے جسم پر پھیرتیں۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 70209;
update hadith set translation_ur = 'ابن عباس رضی اللہ عنہما سے روایت ہے، انہوں نے کہا: نبی ﷺ حسن اور حسین (رضی اللہ عنہما) کو (ان الفاظ سے) پناہ میں دیتے تھے اور فرماتے: ”تمہارے جدِ امجد (ابراہیم علیہ السلام) انہی کلمات سے اسماعیل اور اسحاق کو پناہ میں دیا کرتے تھے: أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّةِ، مِنْ كُلِّ شَيْطَانٍ وَهَامَّةٍ، وَمِنْ كُلِّ عَيْنٍ لَامَّةٍ (میں اللہ کے کامل کلمات کی پناہ مانگتا ہوں ہر شیطان اور ہر زہریلے جانور سے، اور ہر لگ جانے والی نظرِ بد سے)۔“', explanation_ur = 'نبی ﷺ فاطمہ اور علی رضی اللہ عنہم کے بیٹوں حسن اور حسین کو (ان کلمات کے ذریعے) حفاظت میں دیتے اور فرماتے: تمہارے جدِ اعلیٰ ابراہیم علیہ السلام اپنے بیٹوں اسماعیل اور اسحاق کو انہی کلمات سے حفاظت میں دیتے تھے، اور ان کی حفاظت کے لیے کہتے: ”أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّةِ“ — اللہ کے وہ کلمات جو ہر کمال سے متصف اور ہر نقص سے پاک ہیں — ”مِنْ كُلِّ شَيْطَانٍ“ ہر سرکش شیطان سے، ”وَهَامَّةٍ“ اور ہر زہریلے جانور سے جیسے سانپ اور بچھو، ”وَمِنْ كُلِّ عَيْنٍ لَامَّةٍ“ اور ہر اس نظر کے شر سے جو دیکھے جانے والے کو برائی اور بیماری پہنچاتی ہے۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 70307;
update hadith set translation_ur = 'ابن عباس رضی اللہ عنہما سے روایت ہے کہ نبی ﷺ نے فرمایا: ”نظر (لگنا) حق ہے، اور اگر کوئی چیز تقدیر سے آگے بڑھ سکتی تو نظر آگے بڑھ جاتی، اور جب تم سے (نظر کے علاج کے لیے) غسل کرنے کو کہا جائے تو غسل کر دو۔“', explanation_ur = 'نبی ﷺ نے فرمایا: نظر لگنا ثابت اور موجود ہے اور اس کا جانوں پر اثر ہوتا ہے، اور اگر کوئی چیز تقدیر سے آگے بڑھ سکتی تو نظر آگے بڑھ جاتی۔ یہ نظر کے لگنے کی حقیقت کو ثابت کرنے میں مبالغہ ہے اور تمثیل کے طور پر ہے، یہ مطلب نہیں کہ کوئی چیز تقدیر کو ٹال سکتی ہے؛ کیونکہ تقدیر اللہ تعالیٰ کے سابق علم اور اس کی مشیت کے نافذ ہونے کا نام ہے۔ اور جب نظر لگانے والے سے یہ مطالبہ کیا جائے کہ وہ نظر زدہ کے علاج کے لیے اپنے اعضاء دھوئے تو اس پر اعضاء دھونا واجب ہے، خصوصاً جب نظر زدہ کی ہلاکت کا اندیشہ ہو۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 70401;
update hadith set translation_ur = 'عائشہ رضی اللہ عنہا سے روایت ہے، انہوں نے فرمایا: رسول اللہ ﷺ نے مجھے حکم دیا — یا (یوں فرمایا کہ) حکم دیا — کہ نظرِ بد کے لیے دم کروایا جائے۔', explanation_ur = 'عائشہ رضی اللہ عنہا نے فرمایا: نبی ﷺ نے مجھے حکم دیا کہ انسان نظرِ بد سے خود کو دم کرے، یا — راوی کو شک ہے — آپ ﷺ نے حکم دیا کہ ہم نظر لگنے کی وجہ سے کسی دم جاننے والے سے دم کروائیں۔ نظر لگنا یہ ہے کہ نظر لگانے والا کسی چیز پر تعجب کرے تو اللہ تعالیٰ کی جاری کردہ عادت کے مطابق اس چیز کو نقصان پہنچ جائے۔ آنکھ سے گہرے تعلق کی وجہ سے اس فعل کو آنکھ کی طرف منسوب کیا گیا، ورنہ اثر کرنے والی آنکھ نہیں بلکہ روح ہے، اور سبب کے ذریعے اثر اللہ تعالیٰ کے ارادے اور اس کی تخلیق سے ہوتا ہے۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 70402;
update hadith set translation_ur = 'زید بن ارقم رضی اللہ عنہ سے روایت ہے، انہوں نے کہا: یہودیوں میں سے ایک آدمی نے نبی ﷺ پر جادو کیا تو آپ اس کی وجہ سے کئی دن بیمار رہے۔ پھر جبریل علیہ السلام آپ کے پاس آئے اور کہا: یہودیوں میں سے ایک آدمی نے آپ پر جادو کیا ہے، اس نے آپ کے لیے فلاں فلاں کنویں میں گرہیں باندھی ہیں۔ تو رسول اللہ ﷺ نے (کچھ لوگوں کو) بھیجا، انہوں نے وہ گرہیں نکالیں اور لائی گئیں، تو رسول اللہ ﷺ ایسے اٹھ کھڑے ہوئے گویا رسی کی بندش سے آزاد کر دیے گئے ہوں۔ پھر آپ نے اس کا ذکر اس یہودی سے کبھی نہیں کیا اور نہ کبھی اس کے چہرے پر (ناگواری) ظاہر کی۔', explanation_ur = 'یہودیوں میں سے ایک آدمی نے، جس کا نام لبید بن اعصم تھا، نبی ﷺ پر جادو کیا تو آپ اس کی وجہ سے کئی دن تکلیف میں رہے۔ یہ اسی قسم کی چیز تھی جیسی بیماریاں آپ ﷺ کو لاحق ہوتی تھیں، اس میں نبی ﷺ کے لیے کوئی نقص یا عیب نہیں۔ پھر جبریل علیہ السلام آپ کے پاس آئے اور کہا: یہودیوں میں سے ایک آدمی نے آپ پر جادو کیا ہے، اس نے آپ کے لیے گرہیں باندھ کر فلاں فلاں کنویں میں رکھ دی ہیں۔ تو نبی ﷺ نے کنویں کی طرف (لوگ) بھیجے، انہوں نے گرہیں نکالیں اور آپ کے پاس لے آئے، تو آپ ﷺ اٹھ کھڑے ہوئے اور اپنی بیماری سے ایسے صحت یاب ہو گئے گویا کسی بندھن سے کھول دیے گئے ہوں۔ پھر آپ نے اس کا ذکر اس یہودی سے نہیں کیا، اور اس یہودی جادوگر نے آپ ﷺ کے چہرے پر اپنے برے فعل کا کوئی اثر — ناپسندیدگی، غصہ یا بدلہ لینے کا ارادہ — نہیں دیکھا، بلکہ آپ نے دوسرے منافقین کی طرح اس سے بھی خندہ پیشانی اور نرمی کا برتاؤ کیا۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 70501;
update hadith set translation_ur = 'ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی ﷺ نے فرمایا: ”اللہ نے کوئی بیماری نہیں اتاری مگر اس کے لیے شفا بھی اتاری ہے۔“', explanation_ur = 'نبی ﷺ نے فرمایا: اللہ نے جو بھی بیماری اتاری اور مقدر کی، اس کے لیے دوا بھی مقدر کی ہے۔ کبھی انسان علاج کرتا ہے اور شفا نہیں پاتا، تو یہ علاج کے طریقے یا بیماری کی تشخیص سے ناواقفیت کی وجہ سے ہوتا ہے، دوا کے نہ ہونے کی وجہ سے نہیں۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 70601;
update hadith set translation_ur = 'جابر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا: ”ہر بیماری کی دوا ہے، تو جب بیماری کی (صحیح) دوا مل جاتی ہے تو اللہ عزوجل کے حکم سے شفا ہو جاتی ہے۔“', explanation_ur = 'نبی ﷺ نے فرمایا: ہر بیماری کی ایک مناسب دوا ہے۔ جب انسان دوا کو پہچان کر اسے صحیح طریقے سے اور صحیح وقت پر استعمال کر لیتا ہے تو اللہ کے حکم اور مشیت سے اس بیماری سے شفا پا لیتا ہے۔ اور جب اللہ بیمار کو ہلاک کرنا چاہتا ہے تو اسے اس کی دوا سے غافل کر دیتا ہے، یا کسی رکاوٹ سے اس تک پہنچنے سے روک دیتا ہے، یا اس کا اثر روک دیتا ہے تو بیمار ہلاک ہو جاتا ہے؛ اور یہ سب اس کی مشیت اور حکم سے ہوتا ہے جیسا کہ اس کے علم میں پہلے سے ہے۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 70602;
update hadith set translation_ur = 'اسامہ بن شریک رضی اللہ عنہ سے روایت ہے، انہوں نے کہا: میں رسول اللہ ﷺ کے پاس آیا تو آپ کے صحابہ (ایسے ساکت بیٹھے تھے) گویا ان کے سروں پر پرندے بیٹھے ہوں۔ میں نے سلام کیا اور بیٹھ گیا۔ پھر ادھر ادھر سے دیہاتی آئے اور کہنے لگے: اے اللہ کے رسول! کیا ہم علاج کروائیں؟ آپ نے فرمایا: ”علاج کرواؤ، کیونکہ اللہ عزوجل نے کوئی بیماری نہیں رکھی مگر اس کی دوا بھی رکھی ہے، سوائے ایک بیماری کے: بڑھاپا۔“', explanation_ur = 'اسامہ بن شریک رضی اللہ عنہ نے کہا: میں نبی ﷺ کے پاس آیا تو آپ کے صحابہ آپ کے پاس سکون اور وقار سے بیٹھے تھے، ان میں کوئی بے چینی یا ہلکی حرکت نہیں تھی، خاص طور پر نبی ﷺ کی موجودگی میں۔ میں نے سلام کیا اور بیٹھ گیا۔ پھر دائیں بائیں سے دیہاتی آ کر آپ سے سوال کرنے لگے: اے اللہ کے رسول! کیا ہم بیماریوں کا علاج اور دوا کریں؟ آپ نے فرمایا: علاج کرو — اور یہ اباحت (اجازت) کا حکم ہے — کیونکہ اللہ عزوجل نے کوئی بیماری پیدا نہیں کی مگر اس کے لیے شفا دینے والی دوا مقدر کی ہے، سوائے ایک بیماری کے، اور وہ بڑھاپا اور عمر کا ڈھل جانا ہے۔ پس علاج کرنا توکل کے منافی نہیں، جیسے بھوک، پیاس، گرمی اور سردی کو ان کے مخالف اسباب سے دور کرنا توکل کے منافی نہیں؛ بلکہ توحید کی حقیقت تب ہی مکمل ہوتی ہے جب ان اسباب کو اختیار کیا جائے جنہیں اللہ نے تقدیری اور شرعی طور پر ان کے نتائج کا ذریعہ بنایا ہے، اور انہیں معطل کرنا توکل میں بھی خلل ڈالتا ہے اور شرعی حکم میں بھی۔ لہٰذا جو علاج کرے اور شفا نہ پائے تو یہ دوا کے نہ ہونے کی وجہ سے نہیں۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 70603;
update hadith set translation_ur = 'ابن عباس رضی اللہ عنہما سے روایت ہے کہ نبی ﷺ نے فرمایا: ”شفا تین چیزوں میں ہے: پچھنے کے نشتر میں، شہد کے گھونٹ میں، یا آگ سے داغنے میں؛ اور میں اپنی امت کو داغنے سے منع کرتا ہوں۔“', explanation_ur = 'ابن عباس رضی اللہ عنہما نے ذکر کیا کہ شفا تین بنیادی علاجوں میں سے کسی ایک کے استعمال سے حاصل ہوتی ہے۔ اس سے مقصود انہی تین میں حصر نہیں، کیونکہ شفا ان کے علاوہ میں بھی ہو سکتی ہے، بلکہ ان تین کے ذریعے علاج کے بنیادی اصولوں کی طرف توجہ دلائی گئی ہے، اور وہ یہ ہیں: پچھنے کی جگہ پر نشتر کے آلے سے رگ کو کاٹنا اور چیرنا، یا شہد پینا، یا لوہے کو آگ میں گرم کر کے جسم میں درد کی جگہ پر لگانا (داغنا)۔ اور نبی ﷺ نے اپنی امت کو آگ سے داغنے سے کراہت کے طور پر منع فرمایا؛ اس ممانعت کی حکمت یہ ہے کہ اس میں محض شفا کے گمان پر سخت تکلیف اور درد ہے، اور یہ تینوں میں سب سے سخت ہے، لہٰذا ضرورت کے بغیر اسے استعمال نہیں کرنا چاہیے۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 70604;
update hadith set translation_ur = 'ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ انہوں نے رسول اللہ ﷺ کو فرماتے سنا: ”کلونجی میں موت کے سوا ہر بیماری کی شفا ہے۔“ ابن شہاب نے کہا: ”السّام“ سے مراد موت ہے، اور ”الحبۃ السوداء“ سے مراد کلونجی (شونیز) ہے۔', explanation_ur = 'نبی ﷺ نے فرمایا: کلونجی میں ہر بیماری سے عافیت اور حفاظت ہے، سوائے موت کے، یا سوائے اس بیماری کے جس سے اللہ تعالیٰ کے علم میں موت واقع ہونی ہے۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 70605;
update hadith set translation_ur = 'ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا: ”عجوہ (کھجور) جنت سے ہے اور اس میں زہر سے شفا ہے، اور کھمبی ”مَنّ“ میں سے ہے اور اس کا پانی آنکھ کے لیے شفا ہے۔“', explanation_ur = 'نبی ﷺ نے فرمایا: عجوہ — جو مدینہ کی کھجور کی ایک قسم ہے — اس کی اصل جنت سے ہے، اور یہ دنیا کے ان پھلوں کی طرح نہیں جو ایک لحاظ سے مفید اور دوسرے لحاظ سے نقصان دہ ہوتے ہیں؛ اس میں زہر کی دوا ہے اور یہ اس کے ضرر کو دور کرتی ہے۔ اور کھمبی — جو ایک قسم کا پودا ہے — اس ”مَنّ“ میں سے ہے جو اللہ تعالیٰ نے بنی اسرائیل پر اتارا تھا، اور اس کا پانی آنکھ میں ٹپکایا جائے تو آنکھ کی دوا ہے۔', review_note = coalesce(review_note || ' | ', '') || 'ترجمہ آلی – نظرثانی درکار', updated_at = now() where id = 70606;

